// 10개월차 (Day 271~300) · ep 49,50,51,52,53,54
window.JJ_DAYS = Object.assign(window.JJ_DAYS || {}, {"271":{"day":271,"ep":"49","epTitle":"もう一度","epTitleKo":"한 번 더","title":"〜ずにすむ — ~하지 않아도 되다 (다행히 피함)","watch":"49화 중반 · 이타도리와 유타의 격돌","scene":"유타는 리카의 힘까지 끌어내며 이타도리를 몰아붙이고, 이타도리도 온몸으로 맞선다. 이타도리는 자신만 사라지면 더 이상 아무도 다치지 않을 거라고 생각한다. 하지만 유타의 속마음은 따로 있었다.","lines":[{"who":"유타","ja":"本気を出せば、長く戦わずにすむと思うよ。","kana":"ほんきを だせば、ながく たたかわずに すむと おもうよ。","ko":"진심을 내면 오래 싸우지 않아도 될 거야."},{"who":"이타도리","ja":"俺が消えれば、もう誰も傷つかずにすむんだ。","kana":"おれが きえれば、もう だれも きずつかずに すむんだ。","ko":"내가 사라지면 이제 아무도 다치지 않아도 돼."},{"who":"유타","ja":"大丈夫。誰も失わずにすむ方法は考えてあるから。","kana":"だいじょうぶ。だれも うしなわずに すむ ほうほうは かんがえて あるから。","ko":"괜찮아. 아무도 잃지 않아도 되는 방법은 생각해 뒀으니까."}],"words":[{"w":"手数料","r":"てすうりょう","ko":"수수료"},{"w":"損失","r":"そんしつ","ko":"손실"},{"w":"傷つく","r":"きずつく","ko":"다치다, 상처받다"},{"w":"済む","r":"すむ","ko":"끝나다, 해결되다"},{"w":"手術","r":"しゅじゅつ","ko":"수술"},{"w":"違約金","r":"いやくきん","ko":"위약금"},{"w":"早退","r":"そうたい","ko":"조퇴"},{"w":"送料","r":"そうりょう","ko":"배송료"}],"grammar":{"point":"〜ずにすむ","desc":"〜ずにすむ는 '~하지 않고 끝나다, ~하지 않아도 되게 되다'라는 뜻입니다. 원래는 해야 할 수도 있었던 일을 피하게 되어 다행이라는 느낌이 담깁니다. 동사 ない형에서 ない를 빼고 ず를 붙입니다(待たない→待たずに). 단, する는 せずに, 来る는 来ずに(こずに)가 됩니다. 회화에서는 〜ないですむ도 같은 뜻으로 씁니다.","ex":[{"ja":"早めに予約したので、待たずにすみました。","kana":"はやめに よやく したので、またずに すみました。","ko":"일찍 예약해서 기다리지 않아도 됐습니다."},{"ja":"保険に入っていたので、手術代を心配せずにすみました。","kana":"ほけんに はいって いたので、しゅじゅつだいを しんぱい せずに すみました。","ko":"보험에 들어 있어서 수술비 걱정을 하지 않아도 됐습니다."}]},"convert":{"anime":"ギリで遅刻せずにすんだぜ。","real":"おかげさまで、遅刻せずにすみました。","note":"ギリ(아슬아슬)는 젊은 층 속어이고 〜ぜ는 남성 반말 어미입니다. 상사나 고객에게는 おかげさまで와 〜ました로 정중하게 말합니다."},"mission":"미리 준비해서 곤란한 상황을 피한 경험을 〜ずにすみました로 말해 보세요. (예: 서류를 미리 챙겨서 다시 방문하지 않아도 됐다)","missionEx":{"ja":"書類を先に準備したので、もう一度行かずにすみました。","kana":"しょるいを さきに じゅんび したので、もう いちど いかずに すみました。","ko":"서류를 먼저 준비해서 다시 가지 않아도 됐습니다."},"quiz":[{"q":"する를 〜ずに 형태로 바꾸면?","choices":["しずに","さずに","せずに"],"a":2,"why":"する는 예외로 せずに가 됩니다."},{"q":"「일찍 출발해서 지각하지 않아도 됐다」를 일본어로?","choices":["早く出たので、遅刻せずにすんだ。","早く出たのに、遅刻した。","早く出たから、遅刻しなければならない。"],"a":0,"why":"다행히 피한 결과이므로 〜ずにすんだ를 씁니다."},{"q":"「手数料」의 뜻은?","choices":["수수료","위약금","배송료"],"a":0,"why":"手数料(てすうりょう)는 '수수료'입니다. 위약금은 違約金, 배송료는 送料입니다."}]},"272":{"day":272,"ep":"49","epTitle":"もう一度","epTitleKo":"한 번 더","title":"〜ようがない — ~할 방법이 없다","watch":"49화 중반 · 유타의 일격과 반전술식","scene":"격전 끝에 유타는 이타도리를 쓰러뜨리고, 처형이 끝난 것처럼 보인다. 하지만 유타는 반전술식으로 이타도리를 치료해 두었고, 처형은 상층부를 속이기 위한 연기였다. 정신을 차린 이타도리는 어리둥절해한다.","lines":[{"who":"이타도리","ja":"なんで俺、生きてるんだ？説明のしようがないよ。","kana":"なんで おれ、いきてるんだ？せつめいの しようが ないよ。","ko":"나 왜 살아 있는 거야? 설명할 방법이 없어."},{"who":"유타","ja":"上には死んだと伝えるよ。向こうは確かめようがないからね。","kana":"うえには しんだと つたえるよ。むこうは たしかめようが ないからね。","ko":"위에는 죽었다고 전할 거야. 그쪽은 확인할 방법이 없으니까."},{"who":"이타도리","ja":"先輩…ありがたすぎて、何とも言いようがないよ。","kana":"せんぱい…ありがたすぎて、なんとも いいようが ないよ。","ko":"선배… 너무 고마워서 뭐라 말할 수가 없어."}],"words":[{"w":"暗証番号","r":"あんしょうばんごう","ko":"비밀번호"},{"w":"身分証明書","r":"みぶんしょうめいしょ","ko":"신분증"},{"w":"伝える","r":"つたえる","ko":"전하다"},{"w":"宛先","r":"あてさき","ko":"수신처"},{"w":"口座","r":"こうざ","ko":"계좌"},{"w":"治す","r":"なおす","ko":"(병을) 고치다"},{"w":"反転術式","r":"はんてんじゅつしき","ko":"반전술식"},{"w":"通帳","r":"つうちょう","ko":"통장"}],"grammar":{"point":"〜ようがない","desc":"〜ようがない는 '~할 방법이 없다, ~하려야 할 수가 없다'라는 뜻입니다. 하고 싶어도 수단이 없어서 불가능할 때 씁니다. 동사 ます형에서 ます를 빼고 ようがない를 붙입니다(連絡します→連絡しようがない, 言います→言いようがない). する동사는 '명사+のしようがない'(説明のしようがない)로도 씁니다. 〜ようもない라고 하면 더 강조됩니다.","ex":[{"ja":"電話番号が分からないので、連絡しようがありません。","kana":"でんわ ばんごうが わからないので、れんらく しようが ありません。","ko":"전화번호를 몰라서 연락할 방법이 없습니다."},{"ja":"資料がないと、説明のしようがないです。","kana":"しりょうが ないと、せつめいの しようが ないです。","ko":"자료가 없으면 설명할 방법이 없습니다."}]},"convert":{"anime":"んなもん、どうしようもねえだろ。","real":"申し訳ありませんが、今の状況では対応のしようがありません。","note":"んなもん(그런 거)·ねえ는 거친 반말입니다. 고객에게는 申し訳ありませんが로 쿠션을 넣고 〜のしようがありません으로 정중히 사정을 설명합니다."},"mission":"필요한 서류가 없어서 처리를 진행할 수 없는 상황입니다. 고객에게 〜ようがない로 정중히 설명해 보세요.","missionEx":{"ja":"証明書がないと、手続きのしようがないんです。","kana":"しょうめいしょが ないと、てつづきの しようが ないんです。","ko":"증명서가 없으면 처리할 방법이 없습니다."},"quiz":[{"q":"「연락할 방법이 없다」를 일본어로?","choices":["連絡するようがない","連絡しようがない","連絡しようとない"],"a":1,"why":"ます형(連絡し) + ようがない입니다."},{"q":"「言いようがない」의 뜻은?","choices":["뭐라 말할 수가 없다","말할 필요가 없다","말하지 않는 게 좋다"],"a":0,"why":"言い(ます형) + ようがない = 말할 방법이 없다, 뭐라 표현할 수 없다."},{"q":"「通帳」의 뜻은?","choices":["계좌","통장","비밀번호"],"a":1,"why":"通帳(つうちょう)는 '통장'입니다. 계좌는 口座(こうざ), 비밀번호는 暗証番号입니다."}]},"274":{"day":274,"ep":"49","epTitle":"もう一度","epTitleKo":"한 번 더","title":"〜まい — ~하지 않겠다 (부정의 의지·추측)","watch":"49화 후반 · 다시 일어서는 이타도리","scene":"처형을 피한 이타도리는 시부야의 후회를 안은 채로 '한 번 더' 싸우기로 마음먹는다. 같은 실수를 되풀이하지 않겠다고 다짐하는 이타도리에게 유타는 혼자 짊어지지 말고 동료에게 기대라고 말한다.","lines":[{"who":"이타도리","ja":"もう二度と、同じ失敗は繰り返すまい。","kana":"もう にどと、おなじ しっぱいは くりかえすまい。","ko":"다시는 같은 실패를 되풀이하지 않겠어."},{"who":"유타","ja":"一人で背負うまいと決めたなら、僕たちを頼ってよ。","kana":"ひとりで せおうまいと きめたなら、ぼくたちを たよってよ。","ko":"혼자 짊어지지 않겠다고 정했다면 우리한테 기대."},{"who":"이타도리","ja":"ああ。もう逃げまい。もう一度、ちゃんと戦うよ。","kana":"ああ。もう にげまい。もう いちど、ちゃんと たたかうよ。","ko":"응. 이제 도망치지 않을 거야. 한 번 더, 제대로 싸울게."}],"words":[{"w":"借金","r":"しゃっきん","ko":"빚"},{"w":"繰り返す","r":"くりかえす","ko":"반복하다, 되풀이하다"},{"w":"二度と","r":"にどと","ko":"두 번 다시"},{"w":"借り入れ","r":"かりいれ","ko":"차입, 대출"},{"w":"赤字","r":"あかじ","ko":"적자"},{"w":"決心","r":"けっしん","ko":"결심"},{"w":"反省","r":"はんせい","ko":"반성"},{"w":"酒","r":"さけ","ko":"술"}],"grammar":{"point":"〜まい","desc":"〜まい는 조금 문어적인 표현으로 ① 부정의 의지 '~하지 않겠다'(=〜ないつもりだ), ② 부정의 추측 '~하지 않을 것이다'(=〜ないだろう)를 나타냅니다. 5단동사는 사전형+まい(行くまい), 1단동사는 사전형 또는 ます형+まい(食べるまい·食べまい), する는 するまい·すまい입니다. 일상 회화보다는 결심을 밝히는 글이나 다짐에서 많이 쓰며, 〜まいと思う·〜まいと決める 형태가 자주 나옵니다.","ex":[{"ja":"同じミスは二度とするまいと思います。","kana":"おなじ ミスは にどと するまいと おもいます。","ko":"같은 실수는 두 번 다시 하지 않겠다고 생각합니다."},{"ja":"健康のために、もうお酒は飲むまいと決めました。","kana":"けんこうの ために、もう おさけは のむまいと きめました。","ko":"건강을 위해 이제 술은 마시지 않기로 했습니다."}]},"convert":{"anime":"二度と負けねえ。","real":"二度と同じ失敗をしないよう、気をつけます。","note":"負けねえ는 負けない의 거친 남성어입니다. 업무에서 반성할 때는 〜ないよう気をつけます가 자연스럽고, 〜まい는 주로 글이나 굳은 다짐에서 씁니다."},"mission":"업무에서 반성했던 일을 하나 떠올리고, 〜まいと思います로 앞으로의 다짐을 말해 보세요.","missionEx":{"ja":"お客様への連絡は、もう二度と遅らせまいと思います。","kana":"おきゃくさまへの れんらくは、もう にどと おくらせまいと おもいます。","ko":"고객에 대한 연락은 두 번 다시 늦추지 않겠습니다."},"quiz":[{"q":"「行く」에 まい를 붙인 올바른 형태는?","choices":["行くまい","行かまい","行きまい"],"a":0,"why":"5단동사는 사전형 + まい입니다."},{"q":"「飲むまい」의 뜻은?","choices":["마시고 싶다","마셔야 한다","마시지 않겠다"],"a":2,"why":"〜まい는 '~하지 않겠다'는 부정의 의지입니다."},{"q":"「赤字」의 뜻은?","choices":["흑자","적자","빚"],"a":1,"why":"赤字(あかじ)는 '적자', 반대말은 黒字(くろじ)입니다."}]},"275":{"day":275,"ep":"49","epTitle":"もう一度","epTitleKo":"한 번 더","title":"응용 회화 — 49화 총정리","watch":"49화 클라이맥스 · 유타가 이타도리에게 다시 손을 내미는 장면","scene":"처형 연기를 마친 유타는 이타도리에게 모든 것을 혼자 짊어지지 말라고 말한다. 이타도리는 '한 번 더' 주술사로서 사람들을 돕겠다고 다짐하고, 두 사람은 다음 싸움을 위해 함께 움직이기 시작한다.","lines":[{"who":"유타","ja":"君を責めようがないよ。悪いのは君じゃないから。","kana":"きみを せめようが ないよ。わるいのは きみじゃ ないから。","ko":"너를 탓할 수가 없어. 나쁜 건 네가 아니니까."},{"who":"이타도리","ja":"まだ戦えないことはない。もう一度やらせてくれ。","kana":"まだ たたかえない ことは ない。もう いちど やらせて くれ。","ko":"아직 못 싸울 것도 없어. 한 번 더 하게 해 줘."},{"who":"유타","ja":"うん。今度こそ、誰も失わずにすむようにしよう。","kana":"うん。こんどこそ、だれも うしなわずに すむように しよう。","ko":"응. 이번에야말로 아무도 잃지 않도록 하자."}],"words":[{"w":"先方","r":"せんぽう","ko":"상대편(거래 상대)"},{"w":"見通し","r":"みとおし","ko":"전망, 예측"},{"w":"背負い込む","r":"せおいこむ","ko":"혼자 떠맡다"},{"w":"拒否","r":"きょひ","ko":"거부"},{"w":"立ち直る","r":"たちなおる","ko":"다시 일어서다"},{"w":"成果","r":"せいか","ko":"성과"},{"w":"不足","r":"ふそく","ko":"부족"},{"w":"訂正","r":"ていせい","ko":"정정"}],"grammar":{"point":"응용 회화 — 49화 총정리","desc":"〜ないことはない: ~못 할 것도 없다 (できないことはない)\n〜ずにすむ: ~하지 않아도 되어 다행 (待たずにすんだ)\n〜ようがない: ~할 방법이 없다 (連絡しようがない)\n〜まい: ~하지 않겠다 (二度とするまい)","ex":[{"ja":"来週の水曜日なら、ご相談に伺えないことはありません。","kana":"らいしゅうの すいようび なら、ごそうだんに うかがえない ことは ありません。","ko":"다음 주 수요일이라면 상담하러 찾아뵙지 못할 것도 없습니다."},{"ja":"早めにご連絡いただいたので、手続きをやり直さずにすみました。","kana":"はやめに ごれんらく いただいたので、てつづきを やりなおさずに すみました。","ko":"일찍 연락 주셔서 절차를 다시 하지 않아도 됐습니다."}]},"convert":{"anime":"気にすんなって。お前のせいじゃねえよ。","real":"どうかご自分を責めないでください。お客様のせいではありません。","note":"気にすんな·じゃねえ는 친구 사이의 거친 반말입니다. 실수로 자책하는 고객에게는 〜ないでください와 〜ではありません으로 정중하게 안심시킵니다."},"mission":"일본인 고객이 「書類をなくしてしまって、ご迷惑をおかけしました…」라고 사과합니다. ① 탓할 일이 아니라고 안심시키고 ② 재발급이 되니 다시 오지 않아도 된다고 〜ずにすむ로 말한 뒤 ③ 방문 날짜 조정은 〜ないことはない로 답해 보세요.","missionEx":{"ja":"大丈夫です。再発行できるので、もう一度来ずにすみますよ。","kana":"だいじょうぶです。さいはっこう できるので、もう いちど こずに すみますよ。","ko":"괜찮습니다. 재발급이 가능하니 다시 오시지 않아도 됩니다."},"quiz":[{"q":"빈칸에 알맞은 것은? 地図がないので、行き方を調べ（　）。","choices":["ずにすむ","まい","ようがない"],"a":2,"why":"지도가 없어서 '알아볼 방법이 없다'이므로 〜ようがない입니다."},{"q":"「二度と遅刻するまい」의 뜻은?","choices":["지각할지도 모른다","다시는 지각하지 않겠다","지각하지 않아도 됐다"],"a":1,"why":"〜まい는 부정의 의지 '~하지 않겠다'입니다."},{"q":"「背負い込む」의 뜻은?","choices":["혼자 떠맡다","성과","전망"],"a":0,"why":"背負い込む(せおいこむ)는 '혼자 떠맡다'입니다. 성과는 成果, 전망은 見通し입니다."}]},"276":{"day":276,"ep":"50","epTitle":"死滅回游について","epTitleKo":"사멸회유에 대해","title":"〜によると — ~에 따르면 (정보의 출처)","watch":"50화 전반부 · 텐겐을 찾아가는 일행","scene":"이타도리 일행은 켄자쿠가 시작한 '사멸회유'의 정체를 알기 위해 고전 깊숙한 곳에 있는 텐겐을 찾아간다. 들은 정보는 많지만 규칙은 복잡하고 확실한 것은 아직 없다.","lines":[{"who":"후시구로","ja":"噂によると、天元様はこの奥にいるらしい。","kana":"うわさに よると、てんげんさまは この おくに いるらしい。","ko":"소문에 따르면 텐겐 님은 이 안쪽에 있다는 것 같아."},{"who":"이타도리","ja":"先輩の話によれば、ルールがかなり複雑なんだって。","kana":"せんぱいの はなしに よれば、ルールが かなり ふくざつなんだって。","ko":"선배 말에 따르면 규칙이 꽤 복잡하대."},{"who":"유타","ja":"急ごう。残された時間はあまり多くないはずだ。","kana":"いそごう。のこされた じかんは あまり おおく ないはずだ。","ko":"서두르자. 남은 시간은 그리 많지 않을 거야."}],"words":[{"w":"円安","r":"えんやす","ko":"엔저(엔화 약세)"},{"w":"条例","r":"じょうれい","ko":"조례"},{"w":"複雑","r":"ふくざつ","ko":"복잡함"},{"w":"天気予報","r":"てんきよほう","ko":"일기예보"},{"w":"新聞","r":"しんぶん","ko":"신문"},{"w":"調査","r":"ちょうさ","ko":"조사"},{"w":"為替","r":"かわせ","ko":"환율, 환"},{"w":"円高","r":"えんだか","ko":"엔고(엔화 강세)"}],"grammar":{"point":"〜によると / 〜によれば","desc":"〜によると·〜によれば는 '~에 따르면'이라는 뜻으로, 정보의 출처를 밝힐 때 씁니다. 출처 명사 바로 뒤에 붙입니다(ニュースによると). 문장 끝은 전문 표현인 〜そうだ·〜らしい·〜ということだ와 짝을 이루는 경우가 많습니다. 한국어 '뉴스에 따르면 ~래요'와 같은 구조이며, 〜によれば가 조금 더 딱딱한 느낌입니다.","ex":[{"ja":"天気予報によると、明日は雪が降るそうです。","kana":"てんき よほうに よると、あしたは ゆきが ふるそうです。","ko":"일기예보에 따르면 내일은 눈이 온대요."},{"ja":"調査の結果によれば、若い人の加入が増えているそうです。","kana":"ちょうさの けっかに よれば、わかい ひとの かにゅうが ふえて いるそうです。","ko":"조사 결과에 따르면 젊은 사람들의 가입이 늘고 있다고 합니다."}]},"convert":{"anime":"噂じゃ、あいつヤバいらしいぜ。","real":"聞いたところによると、その方はとても厳しいそうです。","note":"〜じゃ(~로는)·ヤバい·〜ぜ는 친구끼리 쓰는 속어 반말입니다. 업무에서는 聞いたところによると로 출처를 밝히고 〜そうです로 정중하게 전합니다."},"mission":"최근 신문이나 뉴스에서 본 경제 소식을 〜によると〜そうです로 고객에게 전해 보세요.","missionEx":{"ja":"新聞によると、来年から金利が上がるそうです。","kana":"しんぶんに よると、らいねんから きんりが あがるそうです。","ko":"신문에 따르면 내년부터 금리가 오른다고 합니다."},"quiz":[{"q":"「일기예보에 따르면 내일은 맑대요」를 일본어로?","choices":["天気予報によって、明日は晴れです。","天気予報のために、明日は晴れるそうです。","天気予報によると、明日は晴れるそうです。"],"a":2,"why":"출처는 〜によると, 문말은 전문 〜そうです로 맞춥니다."},{"q":"〜によると와 가장 잘 어울리는 문장 끝은?","choices":["〜ましょう","〜そうです","〜てください"],"a":1,"why":"출처를 밝힌 뒤에는 '~라고 한다'는 전문 표현이 자연스럽습니다."},{"q":"「複雑」의 뜻은?","choices":["복잡함","규칙","소문"],"a":0,"why":"複雑(ふくざつ)는 '복잡함'입니다."}]},"277":{"day":277,"ep":"50","epTitle":"死滅回游について","epTitleKo":"사멸회유에 대해","title":"〜ということだ — ~라고 한다 / 즉 ~라는 것이다","watch":"50화 중반 · 텐겐이 설명하는 사멸회유의 규칙","scene":"텐겐은 켄자쿠가 일본 각지에 결계를 만들고, 그 안에서 술사들이 서로 싸우게 만드는 '사멸회유'를 시작했다고 설명한다. 참가자는 상대를 쓰러뜨려 점수를 모으고, 일정 점수가 쌓이면 규칙을 하나 추가할 수 있다. 참가를 거부하면 술식을 잃게 된다.","lines":[{"who":"텐겐","ja":"つまり、この国全体が戦いの場になるということだ。","kana":"つまり、この くに ぜんたいが たたかいの ばに なると いう ことだ。","ko":"즉, 이 나라 전체가 싸움터가 된다는 것이다."},{"who":"이타도리","ja":"点数を集めれば、ルールを足せるということか。","kana":"てんすうを あつめれば、ルールを たせると いう ことか。","ko":"점수를 모으면 규칙을 더할 수 있다는 거야?"},{"who":"후시구로","ja":"参加を拒めば、術式を失うということですね。","kana":"さんかを こばめば、じゅつしきを うしなうと いう ことですね。","ko":"참가를 거부하면 술식을 잃는다는 거군요."}],"words":[{"w":"全体","r":"ぜんたい","ko":"전체"},{"w":"点数","r":"てんすう","ko":"점수"},{"w":"登録","r":"とうろく","ko":"등록"},{"w":"集める","r":"あつめる","ko":"모으다"},{"w":"会員","r":"かいいん","ko":"회원"},{"w":"無効","r":"むこう","ko":"무효"},{"w":"有効期限","r":"ゆうこうきげん","ko":"유효기간"},{"w":"つまり","r":"つまり","ko":"즉, 결국"}],"grammar":{"point":"〜ということだ","desc":"〜ということだ는 두 가지로 씁니다. ① 전문: 들은 내용을 객관적으로 전하는 '~라고 한다'(〜そうだ보다 조금 딱딱함). ② 결론·해석: 'つまり〜ということだ(즉 ~라는 것이다)'. 보통형 + ということだ로 연결하고, 회화에서는 〜ってことだ로 줄여 말합니다. 상대의 말을 정리해서 확인하는 〜ということですね는 상담·회의에서 꼭 필요한 표현입니다.","ex":[{"ja":"つまり、来月から保険料が上がるということですね。","kana":"つまり、らいげつから ほけんりょうが あがると いう ことですね。","ko":"즉, 다음 달부터 보험료가 오른다는 거군요."},{"ja":"部長の話では、会議は午後三時からということです。","kana":"ぶちょうの はなしでは、かいぎは ごご さんじからと いう ことです。","ko":"부장님 말씀으로는 회의는 오후 3시부터라고 합니다."}]},"convert":{"anime":"要するに、やるしかねえってことだろ。","real":"つまり、こちらで進めるしかないということですね。","note":"要するに·〜ってことだろ·ねえ는 친구끼리의 거친 축약 반말입니다. 회의에서는 つまり〜ということですね로 상대 말을 정중하게 정리·확인합니다."},"mission":"고객의 긴 설명을 들은 뒤, 핵심을 つまり〜ということですね로 요약해서 확인해 보세요.","missionEx":{"ja":"つまり、毎月の負担を減らしたいということですね。","kana":"つまり、まいつきの ふたんを へらしたいと いう ことですね。","ko":"즉, 매달 부담을 줄이고 싶으시다는 거군요."},"quiz":[{"q":"「〜ってことだ」를 정중하게 말하면?","choices":["〜ということです","〜っていうんです","〜ことにします"],"a":0,"why":"〜ってことだ는 〜ということだ의 회화 축약형입니다."},{"q":"「登録」의 뜻은?","choices":["회원","등록","무효"],"a":1,"why":"登録(とうろく)는 '등록'입니다."},{"q":"「점수를 모으면」이 되도록 빈칸을 채우면? 点数を（　）ば","choices":["集まれ","集め","集めれ"],"a":2,"why":"集める의 가정형은 集めれば입니다."}]},"278":{"day":278,"ep":"50","epTitle":"死滅回游について","epTitleKo":"사멸회유에 대해","title":"〜とのことだ — ~라고 합니다 (전언·메시지 전달)","watch":"50화 중반 · 츠미키가 참가자라는 사실","scene":"텐겐은 후시구로의 누나 츠미키가 켄자쿠가 미리 손을 써 둔 사람 중 하나이며, 이미 사멸회유의 참가자가 되었다고 알린다. 깨어난 참가자에게는 참가를 정해야 하는 기한도 있다. 후시구로는 누나를 구하기 위해 게임에 뛰어들기로 결심한다.","lines":[{"who":"후시구로","ja":"津美紀も、もう参加者になっているとのことですか。","kana":"つみきも、もう さんかしゃに なって いると の ことですか。","ko":"츠미키도 이미 참가자가 되어 있다는 겁니까?"},{"who":"이타도리","ja":"天元様の話だと、期限は十九日とのことだ。","kana":"てんげんさまの はなしだと、きげんは じゅうきゅうにち との ことだ。","ko":"텐겐 님 말로는 기한이 19일이라고 해."},{"who":"후시구로","ja":"なら、迷っている時間はない。俺が行く。","kana":"なら、まよって いる じかんは ない。おれが いく。","ko":"그럼 망설일 시간은 없어. 내가 간다."}],"words":[{"w":"当日","r":"とうじつ","ko":"당일"},{"w":"月末","r":"げつまつ","ko":"월말"},{"w":"伝言","r":"でんごん","ko":"전언, 메시지"},{"w":"目覚める","r":"めざめる","ko":"눈을 뜨다, 깨어나다"},{"w":"翌日","r":"よくじつ","ko":"다음 날"},{"w":"折り返す","r":"おりかえす","ko":"회신하다, 다시 전화하다"},{"w":"担当者","r":"たんとうしゃ","ko":"담당자"},{"w":"至急","r":"しきゅう","ko":"급히, 지급"}],"grammar":{"point":"〜とのことだ","desc":"〜とのことだ는 '~라고 합니다'라는 뜻으로, 다른 사람에게 들은 말이나 메시지를 그대로 전할 때 씁니다. 〜ということだ보다 더 격식 있는 말투라서 비즈니스 전화·메일의 전언에 특히 많이 씁니다. 보통형 + とのことです이며, 명사는 바로 붙일 수 있습니다(明日はお休みとのことです). 확인할 때는 〜とのことですが, 지난 일은 〜とのことでした로 말합니다.","ex":[{"ja":"担当者は本日お休みとのことです。","kana":"たんとうしゃは ほんじつ おやすみと の ことです。","ko":"담당자는 오늘 휴무라고 합니다."},{"ja":"山田様から、後ほど折り返すとのことでした。","kana":"やまださまから、のちほど おりかえすと の ことでした。","ko":"야마다 님께서 나중에 다시 전화하시겠다고 했습니다."}]},"convert":{"anime":"あいつ、ちょっと遅れるってさ。","real":"田中様は少し遅れるとのことです。","note":"〜ってさ는 친구끼리 '~래' 하고 말을 전하는 반말입니다. 비즈니스에서 누군가의 말을 전할 때는 〜とのことです가 기본입니다."},"mission":"고객에게서 걸려온 전화 내용을 동료(또는 상사)에게 〜とのことです로 전달해 보세요.","missionEx":{"ja":"お客様から、明日の面談は午後に変更したいとのことです。","kana":"おきゃくさまから、あしたの めんだんは ごごに へんこう したいと の ことです。","ko":"고객님께서 내일 면담을 오후로 변경하고 싶다고 하십니다."},"quiz":[{"q":"비즈니스 전언으로 가장 알맞은 것은?","choices":["部長は会議中ってさ。","部長は会議中だぜ。","部長は会議中とのことです。"],"a":2,"why":"격식 있는 전언은 〜とのことです입니다."},{"q":"「折り返す」의 뜻은?","choices":["회신하다, 다시 전화하다","반드시","깨어나다"],"a":0,"why":"折り返す(おりかえす)는 전화를 '회신하다'라는 뜻으로 업무에서 자주 씁니다."},{"q":"「翌日」의 뜻은?","choices":["당일","다음 날","월말"],"a":1,"why":"翌日(よくじつ)는 '다음 날'입니다. 당일은 当日(とうじつ)입니다."}]},"279":{"day":279,"ep":"50","epTitle":"死滅回游について","epTitleKo":"사멸회유에 대해","title":"〜というのは — ~라는 것은 (정의·설명)","watch":"50화 후반 · 텐겐이 말하는 켄자쿠의 목적","scene":"텐겐은 사멸회유가 단순한 싸움이 아니라 켄자쿠가 꾸민 더 큰 계획의 일부라고 설명한다. 일행은 '점수', '결계' 같은 낯선 말의 뜻을 하나씩 확인하며 켄자쿠의 진짜 노림수를 파악하려 한다.","lines":[{"who":"이타도리","ja":"死滅回游っていうのは、結局何なんだよ？","kana":"しめつかいゆうって いうのは、けっきょく なんなんだよ？","ko":"사멸회유라는 건 결국 뭐야?"},{"who":"텐겐","ja":"ポイントというのは、相手を倒すともらえる数字のことだ。","kana":"ポイントと いうのは、あいてを たおすと もらえる すうじの ことだ。","ko":"포인트라는 건 상대를 쓰러뜨리면 받는 숫자를 말한다."},{"who":"후시구로","ja":"つまり、あいつの狙いというのは別にあるんですね。","kana":"つまり、あいつの ねらいと いうのは べつに あるんですね。","ko":"즉, 그 녀석의 노림수라는 건 따로 있다는 거군요."}],"words":[{"w":"控除","r":"こうじょ","ko":"공제"},{"w":"数字","r":"すうじ","ko":"숫자"},{"w":"狙い","r":"ねらい","ko":"노림수, 목적"},{"w":"所得","r":"しょとく","ko":"소득"},{"w":"別","r":"べつ","ko":"다름, 따로"},{"w":"保険料","r":"ほけんりょう","ko":"보험료"},{"w":"申告","r":"しんこく","ko":"신고"},{"w":"用語","r":"ようご","ko":"용어"}],"grammar":{"point":"〜というのは (정의·설명)","desc":"〜というのは는 '~라는 것은'이라는 뜻으로, 어떤 말이나 개념을 주제로 내세워 그 뜻을 정의·설명할 때 씁니다. 기본형은 'AというのはBのことです(A란 B를 말합니다)' 또는 'AというのはBということです'입니다. 회화에서는 〜っていうのは, 더 줄이면 〜って로 말합니다. 고객에게 전문 용어를 풀어 설명할 때 꼭 필요한 표현입니다.","ex":[{"ja":"保険料というのは、毎月お支払いいただくお金のことです。","kana":"ほけんりょうと いうのは、まいつき おしはらい いただく おかねの ことです。","ko":"보험료라는 것은 매달 납부하시는 돈을 말합니다."},{"ja":"この手続きというのは、書類の提出と本人確認のことです。","kana":"この てつづきと いうのは、しょるいの ていしゅつと ほんにん かくにんの ことです。","ko":"이 절차라는 것은 서류 제출과 본인 확인을 말합니다."}]},"convert":{"anime":"ポイントって何だよ。","real":"すみません、「ポイント」というのはどういう意味ですか。","note":"〜って何だよ는 따지는 듯한 반말입니다. 모르는 용어를 물을 때는 すみません으로 시작해 〜というのはどういう意味ですか로 정중하게 묻습니다."},"mission":"보험 용어 하나(예: 特約, 満期)를 골라 일본인 고객에게 〜というのは〜のことです로 설명해 보세요.","missionEx":{"ja":"特約というのは、主契約に付ける追加の保障のことです。","kana":"とくやくと いうのは、しゅけいやくに つける ついかの ほしょうの ことです。","ko":"특약이라는 것은 주계약에 붙이는 추가 보장을 말합니다."},"quiz":[{"q":"모르는 용어의 뜻을 정중하게 물을 때 알맞은 것은?","choices":["〜によるとどうですか。","〜というのはどういう意味ですか。","〜ずにすみますか。"],"a":1,"why":"〜というのは로 용어를 주제로 내세워 뜻을 묻습니다."},{"q":"「控除」의 뜻은?","choices":["소득","신고","공제"],"a":2,"why":"控除(こうじょ)는 '공제'입니다. 所得는 소득, 申告는 신고입니다."},{"q":"빈칸에 알맞은 것은? 保険料（　）、毎月払うお金のことです。","choices":["というのは","とのことで","によると"],"a":0,"why":"AというのはBのことです가 정의를 나타내는 기본형입니다."}]},"281":{"day":281,"ep":"50","epTitle":"死滅回游について","epTitleKo":"사멸회유에 대해","title":"응용 회화 — 50화 총정리","watch":"50화 클라이맥스 · 사멸회유 참가를 결심하는 일행","scene":"텐겐의 설명을 모두 들은 일행은 각자 역할을 나눈다. 후시구로는 누나를 구하기 위해, 이타도리는 그런 후시구로를 돕기 위해 결계 안으로 들어가기로 결심한다. 유타는 서로를 믿고 맡기자며 둘을 격려한다.","lines":[{"who":"이타도리","ja":"天元様によると、残された時間はもう少ないってさ。","kana":"てんげんさまに よると、のこされた じかんは もう すくないってさ。","ko":"텐겐 님에 따르면 남은 시간은 이제 얼마 없대."},{"who":"후시구로","ja":"つまり、今すぐ動くしかないということだ。","kana":"つまり、いますぐ うごく しか ないと いう ことだ。","ko":"즉, 지금 당장 움직일 수밖에 없다는 거다."},{"who":"유타","ja":"手分けっていうのは、仲間を信じて任せることだよ。","kana":"てわけって いうのは、なかまを しんじて まかせる ことだよ。","ko":"분담이라는 건 동료를 믿고 맡기는 거야."}],"words":[{"w":"手分け","r":"てわけ","ko":"분담"},{"w":"手配","r":"てはい","ko":"준비, 수배"},{"w":"役割","r":"やくわり","ko":"역할"},{"w":"議題","r":"ぎだい","ko":"의제"},{"w":"業務","r":"ぎょうむ","ko":"업무"},{"w":"確定","r":"かくてい","ko":"확정"},{"w":"日付","r":"ひづけ","ko":"날짜"},{"w":"期日","r":"きじつ","ko":"기일(정해진 날)"}],"grammar":{"point":"응용 회화 — 50화 총정리","desc":"〜によると: ~에 따르면 (天気予報によると〜そうです)\n〜ということだ: ~라고 한다 / 즉 ~라는 것이다 (つまり〜ということですね)\n〜とのことだ: ~라고 합니다·전언 (遅れるとのことです)\n〜というのは: ~라는 것은·정의 (特約というのは〜のことです)","ex":[{"ja":"本社の情報によると、締め切りは来週の金曜日とのことです。","kana":"ほんしゃの じょうほうに よると、しめきりは らいしゅうの きんようびと の ことです。","ko":"본사 정보에 따르면 마감은 다음 주 금요일이라고 합니다."},{"ja":"役割を分けるというのは、各自が責任を持つということです。","kana":"やくわりを わけると いうのは、かくじが せきにんを もつと いう ことです。","ko":"역할을 나눈다는 것은 각자가 책임을 진다는 것입니다."}]},"convert":{"anime":"要は、手分けして行けってこと。","real":"つまり、手分けして進めるということですね。承知しました。","note":"要は·〜ってこと는 친구끼리의 축약 반말입니다. 상사의 지시를 받을 때는 つまり〜ということですね로 정리해 확인하고 承知しました로 마무리합니다."},"mission":"상사가 「本社から連絡があったよ。」라고 말합니다. ① 〜によると로 연락 내용을 확인하고 ② 고객에게 받은 전언을 〜とのことです로 보고한 뒤 ③ 오늘 할 일을 つまり〜ということですね로 정리해 보세요.","missionEx":{"ja":"本社によると、新商品は来月発売とのことです。つまり、今月中にご案内するということですね。","kana":"ほんしゃに よると、しんしょうひんは らいげつ はつばいと の ことです。つまり、こんげつちゅうに ごあんない すると いう ことですね。","ko":"본사에 따르면 신상품은 다음 달 출시라고 합니다. 즉, 이번 달 안에 안내해 드린다는 거군요."},"quiz":[{"q":"전화 메시지를 상사에게 전할 때 알맞은 것은?","choices":["お客様は三時に来られるというのは。","お客様は三時に来られるとのことです。","お客様は三時に来られるによると。"],"a":1,"why":"들은 메시지를 전할 때는 〜とのことです입니다."},{"q":"「뉴스에 따르면」을 일본어로?","choices":["ニュースというのは","ニュースとのことで","ニュースによると"],"a":2,"why":"정보의 출처는 〜によると로 나타냅니다."},{"q":"「役割」의 뜻은?","choices":["역할","정보","마감"],"a":0,"why":"役割(やくわり)는 '역할'입니다."}]},"282":{"day":282,"ep":"51","epTitle":"葦を啣む","epTitleKo":"갈대를 물다","title":"〜に加えて — ~에 더해, ~뿐 아니라","watch":"51화 전반부 · 마키와 마이가 젠인 가문 무기고로 향하는 장면","scene":"시부야 사변 뒤, 마키는 사멸회유에 대비해 동료들에게 줄 주구를 챙기려고 쌍둥이 동생 마이와 함께 본가인 젠인 가문을 찾는다. 전 당주 나오비토의 유언 때문에 가문 안은 어수선하고, 가문 사람들은 마키 자매를 곱게 보지 않는다.","lines":[{"who":"마키","ja":"刀に加えて、槍もいくつか持っていくつもりだ。","kana":"かたなに くわえて、やりも いくつか もって いく つもりだ。","ko":"칼에 더해 창도 몇 개 가져갈 생각이야."},{"who":"마이","ja":"呪具に加えて、倉庫の鍵まで必要だなんて面倒ね。","kana":"じゅぐに くわえて、そうこの かぎまで ひつようだ なんて めんどうね。","ko":"주구에 더해 창고 열쇠까지 필요하다니 귀찮네."},{"who":"마키","ja":"準備に加えて、それなりの覚悟もしておけよ。","kana":"じゅんびに くわえて、それなりの かくごも して おけよ。","ko":"준비에 더해 그만한 각오도 해 둬."}],"words":[{"w":"倉庫","r":"そうこ","ko":"창고"},{"w":"在庫","r":"ざいこ","ko":"재고"},{"w":"梱包","r":"こんぽう","ko":"포장"},{"w":"入荷","r":"にゅうか","ko":"입하"},{"w":"品切れ","r":"しなぎれ","ko":"품절"},{"w":"一族","r":"いちぞく","ko":"일족, 가문"},{"w":"当主","r":"とうしゅ","ko":"당주(집안의 우두머리)"},{"w":"遺言","r":"ゆいごん","ko":"유언"}],"grammar":{"point":"〜に加えて","desc":"〜に加えて는 'A에 더해 B도'라는 뜻으로, 하나를 덧붙여 말할 때 씁니다. 명사 바로 뒤에 붙이며(説明に加えて), 뒤 문장에는 も가 자주 따라옵니다. 회화체 '〜だけじゃなくて'보다 딱딱해서 회의·발표·서류에 잘 어울립니다. 문장 앞에서 'それに加えて(게다가)'처럼 단독으로도 씁니다.","ex":[{"ja":"保険料に加えて、手数料もかかります。","kana":"ほけんりょうに くわえて、てすうりょうも かかります。","ko":"보험료에 더해 수수료도 듭니다."},{"ja":"死亡保障に加えて、医療保障もご検討ください。","kana":"しぼう ほしょうに くわえて、いりょう ほしょうも ごけんとう ください。","ko":"사망 보장에 더해 의료 보장도 검토해 주세요."}]},"convert":{"anime":"これに加えて、あれも持ってけ。","real":"こちらに加えて、あちらもお持ちください。","note":"持ってけ는 持っていけ를 줄인 명령형 반말이라 거칠게 들립니다. 고객에게는 こちら・あちら와 お持ちください로 정중하게 말합니다."},"mission":"고객에게 상품의 기본 보장에 더해 특약도 있다는 것을 〜に加えて로 설명해 보세요.","missionEx":{"ja":"基本の保障に加えて、がんの特約もございます。","kana":"きほんの ほしょうに くわえて、がんの とくやくも ございます。","ko":"기본 보장에 더해 암 특약도 있습니다."},"quiz":[{"q":"「보험료에 더해 수수료도 듭니다」를 일본어로?","choices":["保険料を加えて、手数料もかかります。","保険料に加えて、手数料もかかります。","保険料で加えて、手数料もかかります。"],"a":1,"why":"〜に加えて는 조사 に를 씁니다."},{"q":"「〜に加えて」와 뜻이 가장 가까운 것은?","choices":["〜の代わりに","〜のために","〜だけでなく"],"a":2,"why":"'~뿐 아니라, ~에 더해'라는 뜻이므로 〜だけでなく와 가깝습니다."},{"q":"「遺言」의 읽기는?","choices":["ゆいごん","いこん","ゆうげん"],"a":0,"why":"遺言은 일상어로 ゆいごん이라고 읽습니다."}]},"283":{"day":283,"ep":"51","epTitle":"葦を啣む","epTitleKo":"갈대를 물다","title":"〜に代わって — ~을 대신해서","watch":"51화 중반 · 오기가 마키 자매를 막아서는 장면","scene":"나오비토는 고죠가 없을 경우 메구미를 다음 당주로 삼는다는 유언을 남겼다. 이에 반발한 가문 어른들은 메구미와 마키 자매를 없애려 하고, 무기고에 온 마키 앞을 오기가 가로막는다. 불꽃을 쓰는 오기의 기습에 마키는 큰 부상을 입는다.","lines":[{"who":"오기","ja":"亡き当主に代わって、俺がこの家を守るのだ。","kana":"なき とうしゅに かわって、おれが この いえを まもるのだ。","ko":"돌아가신 당주를 대신해 내가 이 집안을 지키는 것이다."},{"who":"마이","ja":"真希に代わって、今回は私が先に中へ入るわ。","kana":"まきに かわって、こんかいは わたしが さきに なかへ はいるわ。","ko":"마키 대신 이번엔 내가 먼저 안으로 들어갈게."},{"who":"마키","ja":"誰かに代わって戦うつもりなんか、最初からないよ。","kana":"だれかに かわって たたかう つもりなんか、さいしょから ないよ。","ko":"누군가를 대신해 싸울 생각 따윈 처음부터 없어."}],"words":[{"w":"課長","r":"かちょう","ko":"과장"},{"w":"部署","r":"ぶしょ","ko":"부서"},{"w":"代理","r":"だいり","ko":"대리"},{"w":"後継者","r":"こうけいしゃ","ko":"후계자"},{"w":"役員","r":"やくいん","ko":"임원"},{"w":"社内","r":"しゃない","ko":"사내"},{"w":"本社","r":"ほんしゃ","ko":"본사"},{"w":"支店","r":"してん","ko":"지점"}],"grammar":{"point":"〜に代わって","desc":"〜に代わって는 '~을 대신해서'라는 뜻으로, 원래 할 사람 대신 다른 사람이 할 때 씁니다. 명사에 붙이며(部長に代わって), 격식 있는 자리에서는 〜に代わりまして도 씁니다. 한국어 '~을 대신해'와 거의 같지만 조사가 を가 아니라 に라는 점에 주의하세요. '편지 대신 메일이 쓰인다(手紙に代わってメールが使われる)'처럼 시대 변화를 말할 때도 씁니다.","ex":[{"ja":"担当者に代わって、私がご説明します。","kana":"たんとうしゃに かわって、わたしが ごせつめい します。","ko":"담당자를 대신해 제가 설명드리겠습니다."},{"ja":"社長に代わりまして、ご挨拶申し上げます。","kana":"しゃちょうに かわりまして、ごあいさつ もうしあげます。","ko":"사장님을 대신해 인사드립니다."}]},"convert":{"anime":"代わりにやっとくわ。","real":"担当者に代わって、私が対応いたします。","note":"やっとく(やっておく의 축약)는 친구끼리 쓰는 말입니다. 고객 응대에서는 〜に代わって와 対応いたします로 책임 있게 말합니다."},"mission":"담당 설계사가 휴가 중이라 내가 대신 고객 전화를 받았습니다. 〜に代わって로 인사해 보세요.","missionEx":{"ja":"担当の田中に代わって、お電話いたしました。","kana":"たんとうの たなかに かわって、おでんわ いたしました。","ko":"담당 다나카를 대신해 전화드렸습니다."},"quiz":[{"q":"「담당자를 대신해 제가 설명하겠습니다」를 일본어로?","choices":["担当者を代わって、私が説明します。","担当者が代わって、私が説明します。","担当者に代わって、私が説明します。"],"a":2,"why":"'~을 대신해'는 조사 に를 쓴 〜に代わって입니다."},{"q":"「代理」의 뜻은?","choices":["책임","대리","반대"],"a":1,"why":"代理(だいり)는 '대리'입니다."},{"q":"가장 격식 있는 인사는?","choices":["社長に代わりまして、ご挨拶申し上げます。","社長の代わりにやっとくわ。","社長に代わって、挨拶だよ。"],"a":0,"why":"〜に代わりまして + 申し上げます가 가장 정중합니다."}]},"284":{"day":284,"ep":"51","epTitle":"葦を啣む","epTitleKo":"갈대를 물다","title":"〜をこめて — ~을 담아서","watch":"51화 후반 · 마이가 마키에게 마지막 선물을 남기는 장면","scene":"크게 다친 마키와 마이는 저주령이 있는 방에 갇힌다. 마이는 '둘이 하나'인 쌍둥이의 굴레를 끊기 위해 남은 힘을 모두 담아 마키에게 칼 한 자루를 만들어 주고 조용히 떠난다. 이 이별로 마키는 새로운 힘에 눈뜬다.","lines":[{"who":"마이","ja":"心をこめて、あなたのためにこの刀を作ったの。","kana":"こころを こめて、あなたの ために この かたなを つくったの。","ko":"마음을 담아 너를 위해 이 칼을 만들었어."},{"who":"마이","ja":"最後の力をこめて、これをあなたに渡すわ。","kana":"さいごの ちからを こめて、これを あなたに わたすわ。","ko":"마지막 힘을 담아 이걸 너에게 건넬게."},{"who":"마키","ja":"この刀には、真依の思いがこもってるんだな。","kana":"この かたなには、まいの おもいが こもってるんだな。","ko":"이 칼에는 마이의 마음이 담겨 있구나."}],"words":[{"w":"書留","r":"かきとめ","ko":"등기우편"},{"w":"切手","r":"きって","ko":"우표"},{"w":"郵便","r":"ゆうびん","ko":"우편"},{"w":"宅配便","r":"たくはいびん","ko":"택배"},{"w":"印刷","r":"いんさつ","ko":"인쇄"},{"w":"判子","r":"はんこ","ko":"도장"},{"w":"贈る","r":"おくる","ko":"선물하다, 보내다"},{"w":"年末","r":"ねんまつ","ko":"연말"}],"grammar":{"point":"〜をこめて","desc":"〜をこめて는 '~을 담아서'라는 뜻으로, 마음·정성·바람 같은 감정을 행동이나 물건에 담을 때 씁니다. 心をこめて(정성껏), 感謝をこめて(감사를 담아), 愛をこめて(사랑을 담아)가 대표 표현입니다. 한자로는 込めて라고도 씁니다. 명사를 꾸밀 때는 '心をこめた手紙(정성을 담은 편지)'처럼 た형으로 바꿉니다.","ex":[{"ja":"感謝の気持ちをこめて、お礼状を書きました。","kana":"かんしゃの きもちを こめて、おれいじょうを かきました。","ko":"감사의 마음을 담아 감사장을 썼습니다."},{"ja":"心をこめて、お客様の人生設計をお手伝いします。","kana":"こころを こめて、おきゃくさまの じんせい せっけいを おてつだい します。","ko":"정성을 다해 고객님의 인생 설계를 돕겠습니다."}]},"convert":{"anime":"気持ち込めてやったんだから、受け取れよ。","real":"心をこめて準備しましたので、どうぞお受け取りください。","note":"受け取れよ는 명령조 반말입니다. 선물이나 자료를 건넬 때는 どうぞお受け取りください로 공손하게 말합니다."},"mission":"고객 생일에 작은 선물을 보내며 붙일 카드 문구를 〜をこめて로 써 보세요.","missionEx":{"ja":"日頃の感謝をこめて、ささやかな贈り物をお送りします。","kana":"ひごろの かんしゃを こめて、ささやかな おくりものを おおくりします。","ko":"평소의 감사를 담아 작은 선물을 보내 드립니다."},"quiz":[{"q":"「정성껏 만들었습니다」를 일본어로?","choices":["心をこめて作りました。","心にこめて作りました。","心がこめて作りました。"],"a":0,"why":"담는 대상에는 を를 써서 〜をこめて입니다."},{"q":"「감사를 담은 편지」로 알맞은 것은?","choices":["感謝にこめた手紙","感謝をこめて手紙","感謝をこめた手紙"],"a":2,"why":"명사를 꾸밀 때는 〜をこめた + 명사입니다."},{"q":"「書留」의 뜻은?","choices":["우표","등기우편","택배"],"a":1,"why":"書留(かきとめ)는 '등기우편'입니다. 우표는 切手(きって), 택배는 宅配便입니다."}]},"285":{"day":285,"ep":"51","epTitle":"葦を啣む","epTitleKo":"갈대를 물다","title":"〜に向けて — ~을 향해, ~을 목표로","watch":"51화 후반 · 각성한 마키가 다시 일어서는 장면","scene":"마이가 떠난 뒤 주력을 완전히 잃은 마키는 후시구로 토우지처럼 '천여주박'의 육체를 완성한다. 마키는 방 안의 저주령을 순식간에 정리하고, 마이가 남긴 칼을 들고 가문 사람들이 있는 곳으로 향한다.","lines":[{"who":"마키","ja":"次の戦いに向けて、体はもう準備できてる。","kana":"つぎの たたかいに むけて、からだは もう じゅんび できてる。","ko":"다음 싸움을 향해 몸은 이미 준비됐어."},{"who":"젠인 가문 사람","ja":"あいつ、刀を持って本家に向けて歩いてくるぞ！","kana":"あいつ、かたなを もって ほんけに むけて あるいて くるぞ！","ko":"저 녀석, 칼을 들고 본가 쪽으로 걸어오고 있어!"},{"who":"마키","ja":"死滅回游に向けて、まずはここで片をつけておく。","kana":"しめつかいゆうに むけて、まずは ここで かたを つけて おく。","ko":"사멸회유를 앞두고 우선 여기서 결판을 내 두겠어."}],"words":[{"w":"年度末","r":"ねんどまつ","ko":"연도 말"},{"w":"四半期","r":"しはんき","ko":"분기"},{"w":"売上","r":"うりあげ","ko":"매출"},{"w":"黒字","r":"くろじ","ko":"흑자"},{"w":"研修","r":"けんしゅう","ko":"연수"},{"w":"新入社員","r":"しんにゅうしゃいん","ko":"신입사원"},{"w":"決意","r":"けつい","ko":"결의, 굳은 결심"},{"w":"試験","r":"しけん","ko":"시험"}],"grammar":{"point":"〜に向けて","desc":"〜に向けて는 '~을 향해, ~을 목표로'라는 뜻입니다. 장소·방향(東京に向けて出発する)에도, 목표·행사(試験に向けて勉強する)에도 씁니다. 업무에서는 '~을 앞두고 준비한다'는 느낌으로 아주 자주 쓰입니다. 명사를 꾸밀 때는 〜に向けた(来年に向けた計画)가 됩니다.","ex":[{"ja":"来月の試験に向けて、毎晩勉強しています。","kana":"らいげつの しけんに むけて、まいばん べんきょう して います。","ko":"다음 달 시험을 목표로 매일 밤 공부하고 있습니다."},{"ja":"目標達成に向けて、チーム全員で頑張りましょう。","kana":"もくひょう たっせいに むけて、ちーむ ぜんいんで がんばりましょう。","ko":"목표 달성을 향해 팀 전원이 힘냅시다."}]},"convert":{"anime":"試験に向けてガンガンやるぞ。","real":"試験に向けて、しっかり準備いたします。","note":"ガンガン(팍팍, 마구)은 구어 의성어이고 やるぞ는 혼잣말 같은 반말입니다. 상사·고객 앞에서는 しっかり準備いたします로 말합니다."},"mission":"올해 남은 기간의 영업 목표를 위해 무엇을 할지 〜に向けて로 말해 보세요.","missionEx":{"ja":"年末の目標に向けて、毎週三人のお客様に会います。","kana":"ねんまつの もくひょうに むけて、まいしゅう さんにんの おきゃくさまに あいます。","ko":"연말 목표를 향해 매주 고객 세 분을 만납니다."},"quiz":[{"q":"「시험을 앞두고 공부하고 있습니다」를 일본어로?","choices":["試験に向いて勉強しています。","試験を向けて勉強しています。","試験に向けて勉強しています。"],"a":2,"why":"목표를 나타낼 때는 〜に向けて입니다."},{"q":"「내년을 향한 계획」으로 알맞은 것은?","choices":["来年に向けた計画","来年に向けて計画","来年を向けた計画"],"a":0,"why":"명사를 꾸밀 때는 〜に向けた + 명사입니다."},{"q":"「決意」의 읽기는?","choices":["けってい","けつい","けいい"],"a":1,"why":"決意는 けつい입니다. けってい는 決定(결정)입니다."}]},"286":{"day":286,"ep":"51","epTitle":"葦を啣む","epTitleKo":"갈대를 물다","title":"응용 회화 — 51화 총정리","watch":"51화 클라이맥스 · 마이의 칼을 든 마키가 일어서는 장면","scene":"마이의 칼을 손에 든 마키는 상처투성이 몸으로 다시 일어선다. 가문 사람들은 완전히 달라진 마키의 기척에 동요하고, 마키는 마이와 함께 바랐던 일을 혼자서라도 끝내기로 마음먹는다.","lines":[{"who":"마키","ja":"真依の思いをこめて、私はこの刀を振るうんだ。","kana":"まいの おもいを こめて、わたしは この かたなを ふるうんだ。","ko":"마이의 마음을 담아 나는 이 칼을 휘두르는 거야."},{"who":"젠인 가문 사람","ja":"傷に加えて火傷もあるのに、立ち上がったぞ！","kana":"きずに くわえて やけども あるのに、たちあがったぞ！","ko":"상처에 화상까지 있는데 일어섰어!"},{"who":"마키","ja":"あいつに代わって、この家の未来を決めてやる。","kana":"あいつに かわって、この いえの みらいを きめて やる。","ko":"그 애를 대신해 이 집안의 미래를 내가 정해 주지."}],"words":[{"w":"屋敷","r":"やしき","ko":"저택"},{"w":"保証","r":"ほしょう","ko":"보증"},{"w":"火傷","r":"やけど","ko":"화상"},{"w":"補償","r":"ほしょう","ko":"보상"},{"w":"被保険者","r":"ひほけんしゃ","ko":"피보험자"},{"w":"受取人","r":"うけとりにん","ko":"수령인"},{"w":"給付","r":"きゅうふ","ko":"급부, 지급"},{"w":"解約返戻金","r":"かいやくへんれいきん","ko":"해약환급금"}],"grammar":{"point":"응용 회화 — 51화 총정리","desc":"〜に加えて: A에 더해 B도 (保険料に加えて手数料も)\n〜に代わって: ~을 대신해서 (担当者に代わって説明します)\n〜をこめて: 마음·정성을 담아 (感謝をこめて)\n〜に向けて: ~을 향해·목표로 (試験に向けて準備する)\n〜に向けた + 명사: ~을 위한 (来年に向けた計画)","ex":[{"ja":"前の担当者に代わって、新しいプランをご案内します。","kana":"まえの たんとうしゃに かわって、あたらしい ぷらんを ごあんない します。","ko":"전 담당자를 대신해 새 플랜을 안내해 드리겠습니다."},{"ja":"ご家族の将来に向けて、心をこめてご提案します。","kana":"ごかぞくの しょうらいに むけて、こころを こめて ごていあん します。","ko":"가족의 앞날을 위해 정성을 담아 제안드립니다."}]},"convert":{"anime":"お前の代わりに俺がやる。","real":"前の担当者に代わって、私が担当いたします。","note":"お前・俺는 거친 말투입니다. 담당 변경을 알릴 때는 〜に代わって + 担当いたします로 정중하게 말합니다."},"mission":"롤플레이: 일본인 고객이 「担当の方が変わったんですか？」라고 묻습니다. ① 전 담당자를 대신해 내가 맡게 됐다고 답하고 ② 지금 보장에 더해 새 특약도 소개하고 ③ 연말을 목표로 함께 점검하자고 제안해 보세요.","missionEx":{"ja":"はい、前の担当者に代わって私が担当します。今の保障に加えて、新しい特約もご紹介させてください。","kana":"はい、まえの たんとうしゃに かわって わたしが たんとう します。いまの ほしょうに くわえて、あたらしい とくやくも ごしょうかい させて ください。","ko":"네, 전 담당자를 대신해 제가 맡게 되었습니다. 지금 보장에 더해 새 특약도 소개해 드릴게요."},"quiz":[{"q":"「心を（　）手紙を書きました。」 빈칸에 알맞은 것은?","choices":["向けて","こめて","加えて"],"a":1,"why":"마음을 '담아서'는 〜をこめて입니다."},{"q":"「부장님을 대신해 제가 출석합니다」를 일본어로?","choices":["部長に向けて、私が出席します。","部長に加えて、私が出席します。","部長に代わって、私が出席します。"],"a":2,"why":"'~을 대신해'는 〜に代わって입니다."},{"q":"「火傷」의 읽기는?","choices":["やけど","かしょう","ひきず"],"a":0,"why":"火傷는 やけど라고 읽습니다."}]},"288":{"day":288,"ep":"52","epTitle":"熱","epTitleKo":"열","title":"〜てこそ — ~해야 비로소","watch":"52화 전반부 · 마키가 젠인 가문 정예 '炳'과 맞서는 장면","scene":"각성한 마키는 저택에서 가문의 정예 부대 '炳(헤이)' 사람들과 차례로 맞붙는다. 술식을 쓰는 상대들도 압도적인 속도와 힘을 지닌 마키를 따라잡지 못한다. 주력이 없다고 무시당하던 마키가 스스로 실력을 증명하는 장면이다.","lines":[{"who":"마키","ja":"力ってのは、使ってこそ意味があるんだよ。","kana":"ちからってのは、つかって こそ いみが あるんだよ。","ko":"힘이란 건 써야 비로소 의미가 있는 거야."},{"who":"炳 대원","ja":"呪力がないくせに、なぜあんなに速く動けるんだ！","kana":"じゅりょくが ない くせに、なぜ あんなに はやく うごけるんだ！","ko":"주력도 없는 주제에 왜 저렇게 빨리 움직일 수 있는 거야!"},{"who":"마키","ja":"認められてこそ、なんて考えはもう捨てた。","kana":"みとめられて こそ、なんて かんがえは もう すてた。","ko":"인정받아야 비로소, 같은 생각은 이제 버렸어."}],"words":[{"w":"経営","r":"けいえい","ko":"경영"},{"w":"指導","r":"しどう","ko":"지도"},{"w":"訓練","r":"くんれん","ko":"훈련"},{"w":"教育","r":"きょういく","ko":"교육"},{"w":"価値","r":"かち","ko":"가치"},{"w":"製品","r":"せいひん","ko":"제품"},{"w":"商品","r":"しょうひん","ko":"상품"},{"w":"投資","r":"とうし","ko":"투자"}],"grammar":{"point":"〜てこそ","desc":"〜てこそ는 '~해야 비로소, ~하고 나서야 진짜'라는 뜻으로, 어떤 조건이 있어야 진정한 가치나 의미가 생긴다고 강조할 때 씁니다. 동사 て형에 こそ를 붙이고(使ってこそ), 뒤에는 意味がある・本物だ・分かる 같은 말이 자주 옵니다. 한국어 '~해 봐야 안다', '~해야 진짜다'와 비슷합니다. 나쁜 결과를 말할 때는 잘 쓰지 않습니다.","ex":[{"ja":"保険は、もしもの時に役に立ってこそ価値があります。","kana":"ほけんは、もしもの ときに やくに たって こそ かちが あります。","ko":"보험은 만일의 때에 도움이 되어야 비로소 가치가 있습니다."},{"ja":"お客様に信頼されてこそ、本物のプロです。","kana":"おきゃくさまに しんらい されて こそ、ほんものの ぷろ です。","ko":"고객에게 신뢰받아야 진짜 프로입니다."}]},"convert":{"anime":"やってこそだろ、ビビってんじゃねえよ。","real":"実際にやってみてこそ分かることもありますので、ぜひ挑戦してみてください。","note":"ビビってんじゃねえよ(쫄지 마)는 매우 거친 반말입니다. 고객을 격려할 때는 ぜひ〜てみてください로 부드럽게 권합니다."},"mission":"재무설계 일을 하면서 '직접 해 보고 나서야 알게 된 것'을 〜てこそ로 말해 보세요.","missionEx":{"ja":"お客様と直接話してこそ、本当のニーズが分かります。","kana":"おきゃくさまと ちょくせつ はなして こそ、ほんとうの にーずが わかります。","ko":"고객과 직접 이야기해 봐야 진짜 니즈를 알 수 있습니다."},"quiz":[{"q":"「써야 비로소 의미가 있다」를 일본어로?","choices":["使うこそ意味がある。","使ってから意味がある。","使ってこそ意味がある。"],"a":2,"why":"동사 て형 + こそ로 '~해야 비로소'를 나타냅니다."},{"q":"「〜てこそ」의 뜻은?","choices":["~해야 비로소(진짜)","~하는데도","~하는 김에"],"a":0,"why":"조건이 갖춰져야 진정한 의미가 생긴다는 강조입니다."},{"q":"「投資」의 뜻은?","choices":["투자","경영","지도"],"a":0,"why":"投資(とうし)는 '투자'입니다."}]},"289":{"day":289,"ep":"52","epTitle":"熱","epTitleKo":"열","title":"〜ばいい — ~하면 된다","watch":"52화 중반 · 마키와 나오야의 고속 대결","scene":"가문의 실력자 나오야는 동작을 미리 정해 두고 초고속으로 움직이는 술식으로 마키를 몰아붙인다. 하지만 마키는 그 속도에 금세 적응해 반격하고, 자신만만하던 나오야는 점점 궁지에 몰린다.","lines":[{"who":"나오야","ja":"相手より速く動けばええ。それだけの話や。","kana":"あいてより はやく うごけば ええ。それだけの はなしや。","ko":"상대보다 빨리 움직이면 돼. 그뿐인 얘기야."},{"who":"마키","ja":"動きが読めないなら、目が慣れるまで待てばいい。","kana":"うごきが よめないなら、めが なれるまで まてば いい。","ko":"움직임을 못 읽겠으면 눈이 익숙해질 때까지 기다리면 돼."},{"who":"나오야","ja":"どうすればいいんや、こんなはずやない…！","kana":"どう すれば いいんや、こんな はず やない…！","ko":"어떻게 하면 되는 거야, 이럴 리가 없어…!"}],"words":[{"w":"振込","r":"ふりこみ","ko":"계좌이체, 송금"},{"w":"決済","r":"けっさい","ko":"결제"},{"w":"動き","r":"うごき","ko":"움직임"},{"w":"追いつく","r":"おいつく","ko":"따라잡다"},{"w":"引き出す","r":"ひきだす","ko":"인출하다"},{"w":"立て替える","r":"たてかえる","ko":"대신 내다"},{"w":"一括","r":"いっかつ","ko":"일괄(한 번에)"},{"w":"残高","r":"ざんだか","ko":"잔고"}],"grammar":{"point":"〜ばいい","desc":"〜ばいい는 '~하면 된다'는 뜻으로, 방법이나 해결책을 말할 때 씁니다. 동사 ば형(行く→行けば, 待つ→待てば, する→すれば)에 いい를 붙입니다. 'どうすればいいですか(어떻게 하면 됩니까?)'는 조언을 구할 때 꼭 필요한 표현입니다. 〜ばよかった로 바꾸면 '~했으면 좋았을 텐데'라는 후회가 됩니다. (나오야의 ええ는 いい의 간사이 사투리입니다.)","ex":[{"ja":"どの保険を選べばいいですか。","kana":"どの ほけんを えらべば いいですか。","ko":"어느 보험을 고르면 됩니까?"},{"ja":"この書類にサインしていただければいいです。","kana":"この しょるいに さいん して いただければ いいです。","ko":"이 서류에 사인해 주시면 됩니다."}]},"convert":{"anime":"そんなの、やりゃいいだけだろ。","real":"こちらの手順で進めていただければいいです。","note":"やりゃ는 やれば의 구어 축약이고 だけだろ는 단정적인 반말입니다. 고객에게는 〜ていただければいいです(大丈夫です)로 안내합니다."},"mission":"일본 여행 중 길을 잃었습니다. 역까지 어떻게 가면 되는지 〜ばいいですか로 물어보세요.","missionEx":{"ja":"すみません、駅までどう行けばいいですか。","kana":"すみません、えきまで どう いけば いいですか。","ko":"실례합니다, 역까지 어떻게 가면 되나요?"},"quiz":[{"q":"「어느 보험을 고르면 됩니까?」를 일본어로?","choices":["どの保険を選べばいいですか。","どの保険を選んでいいですか。","どの保険を選ぶばいいですか。"],"a":0,"why":"選ぶ의 ば형은 選べば입니다. 選んでいいですか는 '골라도 됩니까?'라는 허락입니다."},{"q":"「する」의 ば형은?","choices":["しれば","すれば","するば"],"a":1,"why":"する는 불규칙 동사로 すれば가 됩니다."},{"q":"「追いつく」의 뜻은?","choices":["시간에 맞추다","고르다","따라잡다"],"a":2,"why":"追いつく(おいつく)는 '따라잡다'입니다."}]},"290":{"day":290,"ep":"52","epTitle":"熱","epTitleKo":"열","title":"〜たらどうですか — ~하는 게 어때요? (제안)","watch":"52화 중반 · 궁지에 몰린 나오야와 마키의 말싸움","scene":"궁지에 몰린 나오야는 그래도 마키를 얕보는 말을 멈추지 않는다. 마키는 차갑게 맞받아치며 싸움을 끝내려 한다. 오늘은 상대에게 무언가를 권하는 '제안' 표현을 배운다.","lines":[{"who":"마키","ja":"もう十分だろ。そろそろ負けを認めたらどうだ？","kana":"もう じゅうぶんだろ。そろそろ まけを みとめたら どうだ？","ko":"이제 충분하잖아. 슬슬 패배를 인정하는 게 어때?"},{"who":"나오야","ja":"お前こそ、怪我する前にさっさと逃げたらどうや。","kana":"おまえこそ、けが する まえに さっさと にげたら どうや。","ko":"너야말로 다치기 전에 얼른 도망치는 게 어때."},{"who":"마키","ja":"文句を言うより先に、手を動かしたらどうだ。","kana":"もんくを いうより さきに、てを うごかしたら どうだ。","ko":"불평하기 전에 손부터 움직이는 게 어때."}],"words":[{"w":"節約","r":"せつやく","ko":"절약"},{"w":"家賃","r":"やちん","ko":"집세, 월세"},{"w":"降参","r":"こうさん","ko":"항복"},{"w":"光熱費","r":"こうねつひ","ko":"공과금(전기·가스·수도)"},{"w":"休憩","r":"きゅうけい","ko":"휴식"},{"w":"生活費","r":"せいかつひ","ko":"생활비"},{"w":"貯蓄","r":"ちょちく","ko":"저축"},{"w":"早めに","r":"はやめに","ko":"일찌감치, 서둘러"}],"grammar":{"point":"〜たらどうですか (제안)","desc":"〜たらどうですか는 '~하는 게 어때요?'라는 제안 표현입니다. 동사 た형에 ら를 붙이고(行ったら, 休んだら) どうですか를 이어 줍니다. 더 공손하게는 〜たらいかがですか, 반말로는 〜たらどう？가 됩니다. 다만 윗사람에게 쓰면 가르치려는 느낌이 들 수 있으니, 그럴 때는 〜てはいかがでしょうか가 더 안전합니다.","ex":[{"ja":"一度、専門家に相談したらどうですか。","kana":"いちど、せんもんかに そうだん したら どうですか。","ko":"한번 전문가와 상담해 보는 게 어때요?"},{"ja":"お疲れのようですから、少し休憩したらいかがですか。","kana":"おつかれの ようですから、すこし きゅうけい したら いかがですか。","ko":"피곤해 보이시니 잠깐 쉬시는 게 어떠세요?"}]},"convert":{"anime":"さっさと謝ったらどうだ。","real":"一度、先方にご連絡なさったらいかがでしょうか。","note":"さっさと(얼른)와 どうだ는 상대를 몰아붙이는 반말입니다. 업무에서 제안할 때는 〜たらいかがでしょうか로 부드럽게 말합니다."},"mission":"보험료가 부담된다는 고객에게 보장 내용을 점검해 보라고 〜たらどうですか(いかがですか)로 제안해 보세요.","missionEx":{"ja":"一度、保障内容を見直したらいかがですか。","kana":"いちど、ほしょう ないようを みなおしたら いかがですか。","ko":"한번 보장 내용을 점검해 보시는 게 어떠세요?"},"quiz":[{"q":"「의사에게 가 보는 게 어때요?」를 일본어로?","choices":["医者に行くらどうですか。","医者に行ったらどうですか。","医者に行ってらどうですか。"],"a":1,"why":"동사 た형 + ら: 行った → 行ったら입니다."},{"q":"가장 공손한 제안은?","choices":["休憩したらどう？","休憩したらどうだ。","休憩したらいかがですか。"],"a":2,"why":"どう를 いかが로 바꾸면 더 정중해집니다."},{"q":"「降参」의 뜻은?","choices":["항복","제안","연락"],"a":0,"why":"降参(こうさん)은 '항복'입니다."}]},"291":{"day":291,"ep":"52","epTitle":"熱","epTitleKo":"열","title":"〜ほうがいい — ~하는 편이 좋다 (충고)","watch":"52화 후반 · 싸움의 열기가 가라앉는 장면","scene":"격렬한 싸움 끝에 마키는 나오야를 쓰러뜨린다. 오기에게 입은 화상의 열기가 아직 몸에 남아 있지만 마키는 멈추지 않는다. 오늘은 상대를 걱정하며 하는 '충고' 표현을 배운다.","lines":[{"who":"마키","ja":"この家には、もう二度と関わらないほうがいい。","kana":"この いえには、もう にどと かかわらない ほうが いい。","ko":"이 집안에는 이제 두 번 다시 엮이지 않는 게 좋아."},{"who":"젠인 가문 사람","ja":"今のあの女には、近づかないほうがいいぞ…。","kana":"いまの あの おんなには、ちかづかない ほうが いいぞ…。","ko":"지금의 저 여자한테는 가까이 가지 않는 게 좋아…."},{"who":"마키","ja":"体の熱が引くまで、少し休んだほうがいいか。","kana":"からだの ねつが ひくまで、すこし やすんだ ほうが いいか。","ko":"몸의 열이 내릴 때까지 좀 쉬는 게 좋으려나."}],"words":[{"w":"高額","r":"こうがく","ko":"고액"},{"w":"無茶","r":"むちゃ","ko":"무리, 터무니없음"},{"w":"少額","r":"しょうがく","ko":"소액"},{"w":"格安","r":"かくやす","ko":"초저가"},{"w":"割高","r":"わりだか","ko":"상대적으로 비쌈"},{"w":"割安","r":"わりやす","ko":"상대적으로 쌈"},{"w":"冷やす","r":"ひやす","ko":"식히다"},{"w":"掛け金","r":"かけきん","ko":"납입금, 부금"}],"grammar":{"point":"〜ほうがいい (충고)","desc":"〜ほうがいい는 '~하는 편이 좋다'는 충고 표현입니다. 긍정은 동사 た형 + ほうがいい(休んだほうがいい), 부정은 ない형 + ほうがいい(行かないほうがいい)를 씁니다. 긍정에서 사전형 대신 た형을 쓰면 충고가 더 분명하게 들립니다. 정중하게는 〜ほうがいいですよ, 더 부드럽게는 〜ほうがいいと思います를 씁니다.","ex":[{"ja":"熱があるなら、今日は早く帰ったほうがいいですよ。","kana":"ねつが あるなら、きょうは はやく かえった ほうが いいですよ。","ko":"열이 있으면 오늘은 일찍 들어가시는 게 좋아요."},{"ja":"若いうちに保険に入ったほうがいいと思います。","kana":"わかい うちに ほけんに はいった ほうが いいと おもいます。","ko":"젊을 때 보험에 가입하는 편이 좋다고 생각합니다."}]},"convert":{"anime":"無茶すんなよ、休んだほうがいいって。","real":"ご無理なさらず、少しお休みになったほうがいいですよ。","note":"すんな(するな의 축약)와 って는 친한 사이의 반말입니다. 고객·상사에게는 ご無理なさらず와 お休みになる로 높여서 충고합니다."},"mission":"건강검진을 미루는 지인에게 〜ほうがいい로 충고해 보세요. 긍정형과 부정형을 하나씩 써 보세요.","missionEx":{"ja":"検査は早めに受けたほうがいいですよ。無理はしないほうがいいです。","kana":"けんさは はやめに うけた ほうが いいですよ。むりは しない ほうが いいです。","ko":"검사는 서둘러 받는 게 좋아요. 무리는 하지 않는 게 좋습니다."},"quiz":[{"q":"「열이 있으면 쉬는 편이 좋아요」를 일본어로?","choices":["熱があるなら、休むのほうがいいですよ。","熱があるなら、休んでほうがいいですよ。","熱があるなら、休んだほうがいいですよ。"],"a":2,"why":"긍정 충고는 동사 た형 + ほうがいい입니다."},{"q":"「가지 않는 편이 좋다」로 알맞은 것은?","choices":["行くないほうがいい","行かないほうがいい","行けないほうがいい"],"a":1,"why":"부정 충고는 ない형 + ほうがいい: 行かないほうがいい입니다."},{"q":"「割高」의 뜻은?","choices":["상대적으로 비쌈","상대적으로 쌈","초저가"],"a":0,"why":"割高(わりだか)는 양·품질에 비해 '비교적 비쌈', 반대말은 割安(わりやす)입니다."}]},"292":{"day":292,"ep":"52","epTitle":"熱","epTitleKo":"열","title":"응용 회화 — 52화 총정리","watch":"52화 엔딩 · 모든 것이 끝난 젠인 가문 저택","scene":"싸움이 끝나고 젠인 가문은 사실상 무너진다. 마키는 마이와 함께 바랐던 대로 가문을 뒤엎었지만, 그 대가는 너무나 컸다. 조용해진 저택을 뒤로하고 마키는 다음 싸움을 향해 걸음을 옮긴다.","lines":[{"who":"마키","ja":"この古い家は、一度壊してこそ変われるんだ。","kana":"この ふるい いえは、いちど こわして こそ かわれるんだ。","ko":"이 낡은 집안은 한 번 부숴야 비로소 바뀔 수 있어."},{"who":"마키","ja":"なあ真依、これから私はどうすればいいと思う？","kana":"なあ まい、これから わたしは どう すれば いいと おもう？","ko":"있잖아 마이, 이제 나는 어떻게 하면 좋을 것 같아?"},{"who":"마키","ja":"…いや、迷うより前を向いて進んだほうがいいな。","kana":"…いや、まようより まえを むいて すすんだ ほうが いいな。","ko":"…아니, 망설이기보다 앞을 보고 나아가는 게 좋겠지."}],"words":[{"w":"相続","r":"そうぞく","ko":"상속"},{"w":"財産","r":"ざいさん","ko":"재산"},{"w":"法人","r":"ほうじん","ko":"법인"},{"w":"崩れる","r":"くずれる","ko":"무너지다"},{"w":"決算","r":"けっさん","ko":"결산"},{"w":"伝統","r":"でんとう","ko":"전통"},{"w":"改正","r":"かいせい","ko":"개정"},{"w":"権利","r":"けんり","ko":"권리"}],"grammar":{"point":"응용 회화 — 52화 총정리","desc":"〜てこそ: ~해야 비로소 (使ってこそ価値がある)\n〜ばいい: ~하면 된다 (どうすればいいですか)\n〜たらどうですか: ~하는 게 어때요 (相談したらどうですか)\n〜たらいかがですか: 더 공손한 제안\n〜ほうがいい: ~하는 편이 좋다 (休んだほうがいい / 行かないほうがいい)","ex":[{"ja":"保険料が心配なら、プランを見直したらどうですか。","kana":"ほけんりょうが しんぱいなら、ぷらんを みなおしたら どうですか。","ko":"보험료가 걱정되시면 플랜을 점검해 보시는 게 어때요?"},{"ja":"早めに準備してこそ、安心した老後が送れます。","kana":"はやめに じゅんび して こそ、あんしん した ろうごが おくれます。","ko":"일찍 준비해야 비로소 안심할 수 있는 노후를 보낼 수 있습니다."}]},"convert":{"anime":"どうすりゃいいんだよ、マジで。","real":"どうすればよろしいでしょうか。","note":"すりゃ(すれば의 축약)와 マジで(진짜로)는 반말 구어입니다. 고객·상사에게 방법을 물을 때는 どうすればよろしいでしょうか로 말합니다."},"mission":"롤플레이: 일본인 고객이 「老後の準備、何から始めればいいですか？」라고 묻습니다. ① 〜ばいい로 첫걸음을 알려 주고 ② 〜ほうがいい로 충고하고 ③ 〜たらいかがですか로 다음 상담을 제안해 보세요.","missionEx":{"ja":"まず毎月の支出を確認すればいいです。早めに始めたほうがいいので、来週一度ご相談にいらっしゃったらいかがですか。","kana":"まず まいつきの ししゅつを かくにん すれば いいです。はやめに はじめた ほうが いいので、らいしゅう いちど ごそうだんに いらっしゃったら いかがですか。","ko":"먼저 매달 지출을 확인하시면 됩니다. 일찍 시작하는 편이 좋으니 다음 주에 한번 상담하러 오시는 게 어떠세요?"},"quiz":[{"q":"「직접 해 봐야 비로소 안다」를 일본어로?","choices":["やってみてこそ分かる。","やってみたこそ分かる。","やってみるこそ分かる。"],"a":0,"why":"て형 + こそ: やってみてこそ입니다."},{"q":"「熱があるなら、休んだ（　）。」 빈칸에 알맞은 것은?","choices":["ばいい","ほうがいい","たらどう"],"a":1,"why":"た형 뒤에 붙어 충고를 나타내는 것은 ほうがいい입니다."},{"q":"「伝統」의 읽기는?","choices":["てんとう","でんどう","でんとう"],"a":2,"why":"伝統는 でんとう라고 읽습니다."}]},"293":{"day":293,"ep":"53","epTitle":"部品","epTitleKo":"부품","title":"〜というより — ~라기보다 (더 정확히 말하면)","watch":"53화 전반부 · 사멸회유를 앞두고 이타도리가 자신의 각오를 털어놓는 장면","scene":"시부야 사변 이후 이타도리는 자신이 겪은 일의 무게를 안은 채 다시 일어선다. 그는 자신을 영웅이 아니라 저주를 없애기 위한 하나의 '부품'으로 여기겠다고 말한다. 후시구로는 그런 이타도리를 걱정스러운 눈으로 바라본다.","lines":[{"who":"이타도리","ja":"俺はヒーローというより、ただの部品なんだよ。","kana":"おれは ひーろー というより、ただの ぶひん なんだよ。","ko":"난 영웅이라기보다 그냥 부품이야."},{"who":"후시구로","ja":"それは覚悟というより、自分を責めてるだけだろ。","kana":"それは かくご というより、じぶんを せめてる だけだろ。","ko":"그건 각오라기보다 그냥 자신을 탓하고 있는 것뿐이잖아."},{"who":"이타도리","ja":"感情で動くというより、役目として動くだけだ。","kana":"かんじょうで うごく というより、やくめ として うごく だけだ。","ko":"감정으로 움직인다기보다 그냥 역할로서 움직일 뿐이야."}],"words":[{"w":"部品","r":"ぶひん","ko":"부품"},{"w":"歯車","r":"はぐるま","ko":"톱니바퀴"},{"w":"本分","r":"ほんぶん","ko":"본분"},{"w":"捨て駒","r":"すてごま","ko":"버리는 말, 희생양"},{"w":"交換可能","r":"こうかんかのう","ko":"교체 가능"},{"w":"消耗品","r":"しょうもうひん","ko":"소모품"},{"w":"代わり","r":"かわり","ko":"대신, 대체"},{"w":"自己責任","r":"じこせきにん","ko":"자기 책임"}],"grammar":{"point":"〜というより","desc":"〜というより는 'A라기보다 (오히려) B'라는 뜻으로, 앞의 표현보다 더 정확한 말로 바꿔 말할 때 씁니다. 명사·형용사·동사의 보통형에 그대로 붙입니다(部品というより・寒いというより・怒るというより). 뒤에 むしろ(오히려)를 넣으면 '정정'하는 느낌이 더 강해집니다. 회의나 상담에서 상대의 말을 부드럽게 고쳐 말할 때 아주 유용합니다.","ex":[{"ja":"これは問題というより、チャンスだと思います。","kana":"これは もんだい というより、ちゃんす だと おもいます。","ko":"이건 문제라기보다 기회라고 생각합니다."},{"ja":"この保険は貯金というより、家族を守る道具です。","kana":"この ほけんは ちょきん というより、かぞくを まもる どうぐ です。","ko":"이 보험은 저금이라기보다 가족을 지키는 도구입니다."}]},"convert":{"anime":"これ、ミスっつーか、仕様じゃね？","real":"これはミスというより、仕様だと思われます。","note":"っつーか는 というか의 거친 구어 축약이고 じゃね？는 じゃない？의 반말입니다. 고객·상사에게는 というより와 だと思われます로 정중하게 바꿉니다."},"mission":"내 일을 '~라기보다 ~이다'로 소개해 보세요. 예: 재무설계사는 판매하는 사람이라기보다 상담하는 사람.","missionEx":{"ja":"私の仕事は販売というより、相談です。","kana":"わたしの しごとは はんばい というより、そうだん です。","ko":"제 일은 판매라기보다 상담입니다."},"quiz":[{"q":"「영웅이라기보다 부품이다」를 일본어로?","choices":["ヒーローというより部品だ。","ヒーローといっても部品だ。","ヒーローより部品というだ。"],"a":0,"why":"'A라기보다 B'는 A + というより + B입니다."},{"q":"〜というより 뒤에 자주 붙어 '오히려'를 강조하는 말은?","choices":["もっと","むしろ","やっと"],"a":1,"why":"〜というより、むしろ〜 형태로 자주 씁니다."},{"q":"「本分」의 뜻은?","choices":["버리는 말","본분","교체 가능"],"a":1,"why":"本分(ほんぶん)은 마땅히 해야 할 본분입니다."}]},"295":{"day":295,"ep":"53","epTitle":"部品","epTitleKo":"부품","title":"〜どころか — ~는커녕 (오히려)","watch":"53화 중반부 · 사멸회유 참가 준비로 정신없는 고전 학생들 장면","scene":"사멸회유가 시작되면서 고전 측에는 쉴 틈조차 없다. 이타도리와 후시구로, 동료들은 남은 시간 안에 누가 어느 결계에 들어갈지 정하고 정보를 나눈다. 하지만 상황은 나아지기는커녕 점점 나빠지기만 한다.","lines":[{"who":"판다","ja":"休憩どころか、ゆっくり寝る時間もないな。","kana":"きゅうけい どころか、ゆっくり ねる じかんも ないな。","ko":"쉬기는커녕 느긋하게 잘 시간도 없네."},{"who":"후시구로","ja":"状況は良くなるどころか、悪くなる一方だ。","kana":"じょうきょうは よく なる どころか、わるく なる いっぽう だ。","ko":"상황은 좋아지기는커녕 나빠지기만 해."},{"who":"이타도리","ja":"説明を聞いたけど、理解どころか頭が真っ白だ。","kana":"せつめいを きいたけど、りかい どころか あたまが まっしろ だ。","ko":"설명을 들었는데 이해는커녕 머리가 새하얘."}],"words":[{"w":"猶予","r":"ゆうよ","ko":"유예"},{"w":"先延ばし","r":"さきのばし","ko":"미룸, 뒤로 미루기"},{"w":"立て込む","r":"たてこむ","ko":"(일이) 몰리다, 붐비다"},{"w":"あたふた","r":"あたふた","ko":"허둥지둥"},{"w":"慌ただしい","r":"あわただしい","ko":"분주하다, 어수선하다"},{"w":"割り振る","r":"わりふる","ko":"할당하다, 배분하다"},{"w":"過密","r":"かみつ","ko":"과밀, 빡빡함"},{"w":"てんてこ舞い","r":"てんてこまい","ko":"정신없이 바쁨"}],"grammar":{"point":"〜どころか","desc":"〜どころか는 'A는커녕'이라는 뜻입니다. 두 가지로 씁니다. ① 'A는커녕 더 쉬운 B도 안 된다'(休憩どころか寝る時間もない) ② '기대와 정반대 결과'(良くなるどころか悪くなった). 명사·동사 보통형에 붙이고, な형용사는 어간이나 な를 붙입니다. 한국어 '~는커녕'과 거의 똑같이 쓰면 됩니다.","ex":[{"ja":"忙しくて、休憩どころか昼ご飯も食べられませんでした。","kana":"いそがしくて、きゅうけい どころか ひるごはんも たべられませんでした。","ko":"바빠서 휴식은커녕 점심도 못 먹었습니다."},{"ja":"丁寧に説明したら、お客様は怒るどころか喜んでくださいました。","kana":"ていねいに せつめい したら、おきゃくさまは おこる どころか よろこんで くださいました。","ko":"정중하게 설명했더니 고객님은 화내기는커녕 기뻐해 주셨습니다."}]},"convert":{"anime":"金、貯まるどころか、マジ減ってんだけど。","real":"貯金が増えるどころか、減ってしまっています。","note":"マジ(진짜)와 減ってんだけど(減っているんだけど의 축약)는 친구끼리 쓰는 말입니다. 상담에서는 〜てしまっています로 차분하게 사실을 전합니다."},"mission":"계획대로 되지 않았던 일을 〜どころか로 말해 보세요. (예: 이번 달 일정, 저축, 다이어트)","missionEx":{"ja":"今月は余裕どころか、時間が全然足りません。","kana":"こんげつは よゆう どころか、じかんが ぜんぜん たりません。","ko":"이번 달은 여유는커녕 시간이 전혀 부족합니다."},"quiz":[{"q":"「쉬기는커녕 잘 시간도 없다」를 일본어로?","choices":["休憩ばかりか、寝る時間もある。","休憩どころか、寝る時間もない。","休憩なのに、寝る時間がない。"],"a":1,"why":"'A는커녕 B도 없다'는 Aどころか Bも〜ない입니다."},{"q":"「좋아지기는커녕 나빠졌다」로 맞는 것은?","choices":["良くなるどころか、悪くなった。","良くなるどころで、悪くなった。","良くなるより、悪くなった。"],"a":0,"why":"정반대 결과를 말할 때 〜どころか를 씁니다."},{"q":"「猶予」의 뜻은?","choices":["납기","유예","마감"],"a":1,"why":"猶予(ゆうよ)는 미루어 주는 것, 유예입니다. 支払猶予 = 지급 유예."}]},"296":{"day":296,"ep":"53","epTitle":"部品","epTitleKo":"부품","title":"〜かのように — 마치 ~인 것처럼","watch":"53화 · 후시구로가 잠든 누나 츠미키를 떠올리는 장면","scene":"후시구로의 누나 츠미키는 오래전 저주에 걸린 뒤 깨어나지 못한 채 잠들어 있다. 그런데 그녀가 사멸회유의 참가자가 되었다는 사실이 드러난다. 후시구로는 누나를 구하기 위해 반드시 게임에 뛰어들겠다고 결심한다.","lines":[{"who":"후시구로","ja":"姉はまるで何もなかったかのように眠っている。","kana":"あねは まるで なにも なかった かのように ねむって いる。","ko":"누나는 마치 아무 일도 없었던 것처럼 잠들어 있어."},{"who":"이타도리","ja":"街はまだ平和であるかのように見えるけど…。","kana":"まちは まだ へいわ である かのように みえる けど…。","ko":"거리는 아직 평화로운 것처럼 보이지만…."},{"who":"후시구로","ja":"突然、全部が決まっていたかのように動き出した。","kana":"とつぜん、ぜんぶが きまって いた かのように うごきだした。","ko":"갑자기 모든 게 정해져 있었던 것처럼 움직이기 시작했어."}],"words":[{"w":"昏睡","r":"こんすい","ko":"혼수(상태)"},{"w":"すやすや","r":"すやすや","ko":"새근새근 (곤히 자는 모양)"},{"w":"見舞い","r":"みまい","ko":"병문안"},{"w":"普段","r":"ふだん","ko":"평소"},{"w":"平和","r":"へいわ","ko":"평화"},{"w":"寝息","r":"ねいき","ko":"잠자는 숨소리"},{"w":"静寂","r":"せいじゃく","ko":"정적"},{"w":"こんこんと","r":"こんこんと","ko":"(잠이) 깊이, 혼곤히"}],"grammar":{"point":"〜かのように","desc":"〜かのように는 '실제로는 그렇지 않은데 마치 ~인 것처럼'이라는 뜻입니다. まるで(마치)와 함께 자주 씁니다. 동사·い형용사는 보통형에 붙이고(知らないかのように), 명사·な형용사는 である를 넣습니다(平和であるかのように). 〜ように보다 '사실은 아니다'라는 느낌이 강하고, 문장 끝에서는 〜かのようだ가 됩니다.","ex":[{"ja":"彼は何も知らないかのように、普段どおり仕事をしていました。","kana":"かれは なにも しらない かのように、ふだん どおり しごとを して いました。","ko":"그는 아무것도 모르는 것처럼 평소대로 일하고 있었습니다."},{"ja":"部長は当然であるかのように、残業を頼んできます。","kana":"ぶちょうは とうぜん である かのように、ざんぎょうを たのんで きます。","ko":"부장님은 당연한 것처럼 야근을 부탁해 옵니다."}]},"convert":{"anime":"あいつ、何もなかったみてーな顔してんじゃん。","real":"あの方は、何もなかったかのようなご様子でした。","note":"みてー는 みたい의 거친 발음, してんじゃん은 しているじゃない의 반말 축약입니다. 보고할 때는 かのような와 ご様子でした로 정중하게 씁니다."},"mission":"일본 여행에서 본 풍경을 '마치 ~인 것처럼'으로 묘사해 보세요.","missionEx":{"ja":"京都の景色は、まるで昔に戻ったかのようでした。","kana":"きょうとの けしきは、まるで むかしに もどった かのよう でした。","ko":"교토의 경치는 마치 옛날로 돌아간 것 같았습니다."},"quiz":[{"q":"「마치 꿈인 것처럼」으로 맞는 것은?","choices":["まるで夢のおかげで","まるで夢であるかのように","まるで夢でないように"],"a":1,"why":"명사에는 である를 넣어 〜であるかのように로 씁니다."},{"q":"〜かのように와 자주 함께 쓰는 부사는?","choices":["きっと","やっと","まるで"],"a":2,"why":"まるで〜かのように(마치 ~인 것처럼)가 짝입니다."},{"q":"「すやすや」의 뜻은?","choices":["새근새근 (곤히 자는 모양)","쿵쾅쿵쾅","반짝반짝"],"a":0,"why":"すやすや는 곤히 잠든 숨소리를 나타내는 의태어입니다."}]},"297":{"day":297,"ep":"53","epTitle":"部品","epTitleKo":"부품","title":"〜に限らず — ~뿐만 아니라 (~에 한하지 않고)","watch":"53화 후반부 · 사멸회유의 규칙을 하나하나 확인하는 장면","scene":"사멸회유는 술사뿐 아니라 갑자기 술식에 눈뜬 일반인까지 끌어들이는 위험한 게임이다. 결계 안에 들어간 사람은 누구든 참가자가 되고, 규칙을 어기면 큰 대가를 치른다. 이타도리와 후시구로는 규칙을 꼼꼼히 확인한다.","lines":[{"who":"후시구로","ja":"術師に限らず、一般人も参加させられている。","kana":"じゅつしに かぎらず、いっぱんじんも さんか させられて いる。","ko":"술사뿐만 아니라 일반인도 참가하게 되어 있어."},{"who":"이타도리","ja":"年齢に限らず、中にいる全員が危険ってことか。","kana":"ねんれいに かぎらず、なかに いる ぜんいんが きけん って ことか。","ko":"나이에 상관없이 안에 있는 전원이 위험하다는 거구나."},{"who":"후시구로","ja":"この規則は場所に限らず、全部の結界で同じだ。","kana":"この きそくは ばしょに かぎらず、ぜんぶの けっかいで おなじ だ。","ko":"이 규칙은 장소에 상관없이 모든 결계에서 똑같아."}],"words":[{"w":"強制","r":"きょうせい","ko":"강제"},{"w":"義務","r":"ぎむ","ko":"의무"},{"w":"違反","r":"いはん","ko":"위반"},{"w":"罰則","r":"ばっそく","ko":"벌칙"},{"w":"対象","r":"たいしょう","ko":"대상"},{"w":"市民","r":"しみん","ko":"시민"},{"w":"例外","r":"れいがい","ko":"예외"},{"w":"無差別","r":"むさべつ","ko":"무차별"}],"grammar":{"point":"〜に限らず","desc":"〜に限らず는 'A에 한하지 않고, A뿐만 아니라 (B도)'라는 뜻으로 범위를 넓힐 때 씁니다. 명사 + に限らず 형태이고, 뒤에 も・全員・どこでも・誰でも 같은 말이 자주 옵니다. 반대로 범위를 좁히는 말은 〜に限り(~에 한해)입니다. 안내문·상품 설명 같은 공식적인 글에서 특히 자주 보입니다.","ex":[{"ja":"この保険は年齢に限らず、どなたでも加入できます。","kana":"この ほけんは ねんれいに かぎらず、どなたでも かにゅう できます。","ko":"이 보험은 나이에 상관없이 누구나 가입할 수 있습니다."},{"ja":"週末に限らず、平日の夜もご相談いただけます。","kana":"しゅうまつに かぎらず、へいじつの よるも ごそうだん いただけます。","ko":"주말뿐만 아니라 평일 밤에도 상담하실 수 있습니다."}]},"convert":{"anime":"大人とか子どもとか関係ねーし、全員参加な。","real":"年齢に限らず、皆様にご参加いただけます。","note":"関係ねーし는 関係ないし의 거친 축약이고 〜な는 명령조 반말입니다. 안내할 때는 〜に限らず와 ご参加いただけます로 정중하게 범위를 설명합니다."},"mission":"고객에게 상담 대상이 넓다는 것을 〜に限らず로 안내해 보세요.","missionEx":{"ja":"会社員に限らず、自営業の方もご相談ください。","kana":"かいしゃいんに かぎらず、じえいぎょうの かたも ごそうだん ください。","ko":"회사원뿐만 아니라 자영업자분도 상담해 주세요."},"quiz":[{"q":"「일본뿐만 아니라 해외에서도」를 일본어로?","choices":["日本に限って、海外でも","日本だけで、海外でも","日本に限らず、海外でも"],"a":2,"why":"범위를 넓힐 때는 〜に限らず를 씁니다. 〜に限って는 반대로 좁히는 말입니다."},{"q":"〜に限らず 앞에 오는 것은?","choices":["동사 て형","명사","い형용사 과거형"],"a":1,"why":"명사 + に限らず 형태로 씁니다."},{"q":"「罰則」의 뜻은?","choices":["벌칙","의무","예외"],"a":0,"why":"罰則(ばっそく)은 규칙을 어겼을 때의 벌칙입니다."}]},"298":{"day":298,"ep":"53","epTitle":"部品","epTitleKo":"부품","title":"응용 회화 — 53화 총정리","watch":"53화 클라이맥스 · 동료들이 맡을 결계를 정하고 각자 흩어지는 장면","scene":"고전 측은 결계를 나누어 맡기로 한다. 이타도리와 후시구로는 도쿄 제1결계로, 하카리와 판다는 도쿄 제2결계로 향한다. 서로 다른 길을 가지만, 목표는 하나다.","lines":[{"who":"하카리","ja":"これは作戦というより、ただのギャンブルだな。","kana":"これは さくせん というより、ただの ぎゃんぶる だな。","ko":"이건 작전이라기보다 그냥 도박이네."},{"who":"후시구로","ja":"成功どころか、生きて帰れるかも分からない。","kana":"せいこう どころか、いきて かえれるかも わからない。","ko":"성공은커녕 살아서 돌아올 수 있을지도 몰라."},{"who":"이타도리","ja":"俺に限らず、みんなもう覚悟はできてるよ。","kana":"おれに かぎらず、みんな もう かくごは できてるよ。","ko":"나뿐만 아니라 다들 이미 각오는 되어 있어."}],"words":[{"w":"連携","r":"れんけい","ko":"연계, 공조"},{"w":"段取り","r":"だんどり","ko":"일의 순서, 준비"},{"w":"健闘","r":"けんとう","ko":"건투"},{"w":"共倒れ","r":"ともだおれ","ko":"함께 쓰러짐, 공멸"},{"w":"分担","r":"ぶんたん","ko":"분담"},{"w":"拠点","r":"きょてん","ko":"거점"},{"w":"合流","r":"ごうりゅう","ko":"합류"},{"w":"別行動","r":"べつこうどう","ko":"따로 행동함"}],"grammar":{"point":"응용 회화 — 53화 총정리","desc":"〜というより: A라기보다 B (더 정확한 말로 바꿔 말하기)\n〜どころか: A는커녕 (훨씬 못하거나 정반대 결과)\n〜かのように: 실제로는 아닌데 마치 ~인 것처럼\n〜に限らず: A뿐만 아니라 (범위를 넓힐 때)","ex":[{"ja":"この件は営業部に限らず、全員で協力しましょう。","kana":"この けんは えいぎょうぶに かぎらず、ぜんいんで きょうりょく しましょう。","ko":"이 건은 영업부뿐만 아니라 전원이 협력합시다."},{"ja":"連絡が遅れて、合流どころか会議も始められませんでした。","kana":"れんらくが おくれて、ごうりゅう どころか かいぎも はじめられませんでした。","ko":"연락이 늦어져서 합류는커녕 회의도 시작하지 못했습니다."}]},"convert":{"anime":"作戦？んなもんねーよ、行きゃわかる。","real":"作戦というより、現地で状況を見て判断いたします。","note":"んなもんねーよ(そんなものないよ)와 行きゃ(行けば)는 거친 축약입니다. 업무에서는 〜というより로 생각을 정리하고 判断いたします로 정중하게 마무리합니다."},"mission":"롤플레이: 일본인 동료가 「このプロジェクト、どう分担しますか？」라고 묻습니다. ① 〜というより로 이 일의 성격을 설명하고 ② 〜に限らず로 누가 참여할지 답해 보세요.","missionEx":{"ja":"これは営業というより相談なので、私に限らず皆さんの意見も聞きたいです。","kana":"これは えいぎょう というより そうだん なので、わたしに かぎらず みなさんの いけんも ききたいです。","ko":"이건 영업이라기보다 상담이니까, 저뿐만 아니라 여러분의 의견도 듣고 싶습니다."},"quiz":[{"q":"「작전이라기보다 도박이다」를 일본어로?","choices":["作戦どころかギャンブルだ。","作戦というより、ギャンブルだ。","作戦に限らずギャンブルだ。"],"a":1,"why":"더 정확한 말로 바꿔 말할 때는 〜というより입니다."},{"q":"「나뿐만 아니라 모두」를 일본어로?","choices":["私というより、みんな","私どころか、みんな","私に限らず、みんな"],"a":2,"why":"범위를 넓히는 '~뿐만 아니라'는 〜に限らず입니다."},{"q":"「分担」의 뜻은?","choices":["분담","협력","합류"],"a":0,"why":"分担(ぶんたん)은 일을 나누어 맡는 것입니다."}]},"299":{"day":299,"ep":"54","epTitle":"東京第1結界①","epTitleKo":"도쿄 제1결계 1","title":"〜ないうちに — ~하기 전에 (늦기 전에)","watch":"54화 전반부 · 이타도리와 후시구로가 도쿄 제1결계에 들어가는 장면","scene":"이타도리와 후시구로는 함께 도쿄 제1결계 안으로 들어간다. 그러나 들어가자마자 두 사람은 결계 안 서로 다른 곳으로 흩어져 하늘에서 떨어지게 된다. 이타도리는 일이 더 커지기 전에 후시구로와 다시 만나려고 서두른다.","lines":[{"who":"이타도리","ja":"地面に落ちないうちに、なんとかしないと！","kana":"じめんに おちない うちに、なんとか しないと！","ko":"땅에 떨어지기 전에 어떻게든 해야 해!"},{"who":"이타도리","ja":"暗くならないうちに、早く伏黒と合流しなきゃ。","kana":"くらく ならない うちに、はやく ふしぐろと ごうりゅう しなきゃ。","ko":"어두워지기 전에 빨리 후시구로랑 합류해야 해."},{"who":"후시구로","ja":"敵に見つからないうちに、急いでここを離れよう。","kana":"てきに みつからない うちに、いそいで ここを はなれよう。","ko":"적에게 들키기 전에 서둘러 여기를 떠나자."}],"words":[{"w":"真っ逆さま","r":"まっさかさま","ko":"곤두박질"},{"w":"どすん","r":"どすん","ko":"쿵 (무거운 것이 떨어지는 소리)"},{"w":"落ちる","r":"おちる","ko":"떨어지다"},{"w":"着地","r":"ちゃくち","ko":"착지"},{"w":"夜明け","r":"よあけ","ko":"새벽, 동틀 녘"},{"w":"墜落","r":"ついらく","ko":"추락"},{"w":"冷める","r":"さめる","ko":"식다"},{"w":"早急","r":"さっきゅう","ko":"시급함, 서둘러"}],"grammar":{"point":"〜ないうちに","desc":"〜ないうちに는 '~하기 전에(그렇게 되기 전에)'라는 뜻입니다. 동사 ない형 + うちに 형태입니다. 단순한 순서를 말하는 〜前に와 달리 '그렇게 되면 곤란하니까 그 전에'라는 긴박한 느낌이 있습니다. 冷めないうちに(식기 전에)・忘れないうちに(잊기 전에)는 통째로 외워 두면 바로 쓸 수 있습니다.","ex":[{"ja":"冷めないうちに、どうぞ召し上がってください。","kana":"さめない うちに、どうぞ めしあがって ください。","ko":"식기 전에 어서 드세요."},{"ja":"忘れないうちに、今日の内容をメモしておきます。","kana":"わすれない うちに、きょうの ないようを めも して おきます。","ko":"잊기 전에 오늘 내용을 메모해 두겠습니다."}]},"convert":{"anime":"冷めねーうちに食っちまえよ。","real":"冷めないうちに、お召し上がりください。","note":"冷めねー는 冷めない의 거친 발음, 食っちまえ는 食べてしまえ의 거친 명령입니다. 손님에게는 お召し上がりください로 권합니다."},"mission":"고객에게 마감 전에 서류를 내 달라고 〜ないうちに로 부탁해 보세요.","missionEx":{"ja":"締め切りが過ぎないうちに、書類を出してください。","kana":"しめきりが すぎない うちに、しょるいを だして ください。","ko":"마감이 지나기 전에 서류를 내 주세요."},"quiz":[{"q":"「식기 전에 드세요」로 맞는 것은?","choices":["冷めるうちに、どうぞ。","冷めないうちに、どうぞ。","冷めたうちに、どうぞ。"],"a":1,"why":"'~하기 전에(늦기 전에)'는 ない형 + うちに입니다."},{"q":"〜ないうちに에 가장 가까운 한국어는?","choices":["~한 후에","~하는 동안","~하기 전에(늦기 전에)"],"a":2,"why":"그렇게 되기 전에 서둘러 한다는 뜻입니다."},{"q":"「墜落」의 뜻은?","choices":["추락","서두름","착지"],"a":0,"why":"墜落(ついらく)는 높은 곳에서 떨어지는 추락입니다. 착지는 着地입니다."}]}});
